import fs from 'fs';

const hexagrams = JSON.parse(fs.readFileSync('src/data/hexagrams.json', 'utf-8'));

const yaoData = {};

function addYao(hexagramId, position, yaoType, fortune, yaoText, yaoTextTranslation, xiangText, xiangTextTranslation, heloNumber, heloDescription) {
  if (!yaoData[hexagramId]) {
    yaoData[hexagramId] = [];
  }
  yaoData[hexagramId].push({
    hexagramId,
    position,
    yaoType,
    fortune,
    yaoText,
    yaoTextTranslation,
    xiangText,
    xiangTextTranslation,
    heloNumber,
    heloDescription
  });
}

// 1. 乾卦 (111111)
addYao(1, 1, '初九', '平', '潜龙勿用。', '潜藏的龙，无法施展。', '潜龙勿用，阳在下也。', '潜藏的龙，无法施展，因为初九阳爻处在一卦的下位，所以压抑难伸。', '9', '得此爻者，宜沉稳待机，若一动作即生灾疾，谋事不利，谨防小人。做官的会有阻力。经商的会有阻滞。女命则兴家业，孕生子。');
addYao(1, 2, '九二', '吉', '见龙在田，利见大人。', '龙出现在田野之上，利于出现大人物。', '见龙在田，德施普也。', '龙出现在田野之上，说明君子的道德品行已经得到了广泛的传播。', '9', '得此爻者，万事如意，谋望顺遂，财利亨通，大有所获。做官的将大展宏图，商人将财源广进。女命则主夫荣子贵。');
addYao(1, 3, '九三', '平', '君子终日乾乾，夕惕若厉，无咎。', '君子整天勤奋努力，到了晚上还要警惕戒备，这样即使遇到危险，也不会有灾祸。', '终日乾乾，反复道也。', '整天勤奋努力，说明君子在反复地实践着天道。', '9', '得此爻者，宜谨慎行事，不可懈怠，否则会有灾患。做官的须防小人的陷害。经商的会有阻滞。女命则主有口舌之争，家宅不安。');
addYao(1, 4, '九四', '平', '或跃在渊，无咎。', '龙或跃出水面，或退居深渊，没有灾祸。', '或跃在渊，进无咎也。', '龙或跃出水面，或退居深渊，说明进退都没有灾祸。', '9', '得此爻者，进退自如，有贵人相助，营谋有利。做官的会升迁，经商的会获利。女命则主有喜庆之事。');
addYao(1, 5, '九五', '吉', '飞龙在天，利见大人。', '龙飞腾在天上，利于出现大人物。', '飞龙在天，大人造也。', '龙飞腾在天上，说明大人物已经出现，正在创造伟大的事业。', '9', '得此爻者，万事如意，大吉大利，事业有成，名利双收。做官的会身居要职，商人会财源滚滚。女命则主夫荣子贵，大吉大利。');
addYao(1, 6, '上九', '凶', '亢龙有悔。', '龙飞得太高了，会有悔恨。', '亢龙有悔，盈不可久也。', '龙飞得太高了，会有悔恨，因为满盈是不可能长久保持的。', '9', '得此爻者，宜急流勇退，不可过于强求，否则会有灾祸。做官的须防功高震主，商人须防钱财散尽。女命则主有损伤之灾。');

// 2. 坤卦 (000000)
addYao(2, 1, '初六', '平', '履霜，坚冰至。', '踩到了薄霜，预示着坚冰即将到来。', '履霜坚冰，阴始凝也；驯致其道，至坚冰也。', '踩到了薄霜，预示着坚冰即将到来，说明阴气开始凝结了；顺着这个趋势发展下去，就会达到坚冰的程度。', '6', '得此爻者，宜防微杜渐，不可大意，否则会有灾祸。做官的须防小人的谗言，经商的须防亏损。女命则主有忧愁之事。');
addYao(2, 2, '六二', '吉', '直方大，不习无不利。', '正直、方正、宏大，即使不学习也没有不利。', '六二之动，直以方也；不习无不利，地道光也。', '六二爻的行动，是正直而方正的；即使不学习也没有不利，说明地道是光明的。', '6', '得此爻者，正直无私，万事亨通，名利双收。做官的会受到重用，商人会获利丰厚。女命则主贤淑有德，大吉大利。');
addYao(2, 3, '六三', '平', '含章可贞，或从王事，无成有终。', '蕴含美好的文采，可以保持贞正，或者跟从君王做事，没有成就但有好的结局。', '含章可贞，以时发也；或从王事，知光大也。', '蕴含美好的文采，可以保持贞正，说明要等待时机发挥；或者跟从君王做事，说明智慧得到了发扬光大。', '6', '得此爻者，宜静待时机，不可急躁，否则会有损失。做官的须等待机会，经商的须谨慎行事。女命则主有才华，但须防嫉妒。');
addYao(2, 4, '六四', '平', '括囊，无咎无誉。', '把口袋扎紧，没有灾祸也没有荣誉。', '括囊无咎，慎不害也。', '把口袋扎紧，没有灾祸，说明谨慎行事就不会受到伤害。', '6', '得此爻者，宜谨言慎行，不可多言，否则会有是非。做官的须防言多必失，经商的须防泄露机密。女命则主口舌之争。');
addYao(2, 5, '六五', '吉', '黄裳，元吉。', '黄色的衣裳，大吉大利。', '黄裳元吉，文在中也。', '黄色的衣裳，大吉大利，说明美好的文采蕴含在内心之中。', '6', '得此爻者，万事如意，大吉大利，有贵人相助，事业有成。做官的会身居要职，商人会财源广进。女命则主贵夫人之命。');
addYao(2, 6, '上六', '凶', '龙战于野，其血玄黄。', '龙在野外争斗，流出的血是玄黄色的。', '龙战于野，其道穷也。', '龙在野外争斗，说明已经到了穷途末路的地步。', '6', '得此爻者，须防争斗之灾，宜和平相处，否则会有大的损失。做官的须防同僚之争，经商的须防同行之争。女命则主有血光之灾。');

// 3. 屯卦 (010001)
addYao(3, 1, '初九', '平', '盘桓，利居贞，利建侯。', '徘徊难进。这是有利于居住的卜问。巫遇此爻，有利于建国封侯。', '虽盘桓，志行正也;以贵下贱，大得民也。', '虽然徘徊难进，但志行贞正。初九居六二阴爻之下，象徵以尊贵而俯顺于低贱，因而大得民心。', '', '得此爻者，安分守己者则无忧，躁动者不利。做官的暂时未受到重用，坚守正道，好运可期。女命则为良妇而兴家。');
addYao(3, 2, '六二', '平', '屯如邅如，乘马班如。匪寇婚构，女子贞不字，十年乃字。', '梭巡不前。行路踌躇，驾着马车原地回旋，不是前来抢劫，而是迎娶新娘。占得这个女子不能孕育，十年才能怀孕。', '六二之难，乘刚也;十年乃字，反常也。', '六二之爻预示艰难，因为处在初九阳爻之上。十年才能怀孕，这是反常现象。', '', '得此爻者，有婚嫁之喜事。做官的权柄日盛。');
addYao(3, 3, '六三', '凶', '即鹿无虞，唯入于林中。君子几，不如舍。往吝。', '追捕野鹿，没有充当向导的官员。思忖着鹿逃入山林。君子机灵，认为不如放弃。深入山林，认为会有危险。', '即鹿无虞，以从禽也。君子舍之，往吝，穷也。', '追捕野鹿，没有充当向导的官员，意在追逐走兽。君子放弃那野鹿，知道深入山林会有危险，因而除此别无他法。', '', '得此爻者，须安分守己，否则会有灾难。做官的有贪污之嫌，有被停职降职之忧。');
addYao(3, 4, '六四', '吉', '乘马班如，求婚构，往吉，无不利。', '驾着马车原地回旋，这是寻求婿姻。放胆前进，必定吉利。', '求而往，明也。', '敢于追求，勇于深入，因为其人深明形势。', '', '得此爻者，谋事可成，百事和合，会得到朋友的帮助，大吉大利。做官的将会名声显赫，有升迁之机。');
addYao(3, 5, '九五', '平', '屯其膏，小贞吉，大贞凶。', '屯积肥肉。筮遇此爻，问小事则吉，问大事则凶。', '屯其膏，施未光也。', '"屯积肥肉"，意思是施舍不广。', '', '得此爻者，谋事者切勿急躁，小事可成，大事无望，甚至会招来凶祸。');
addYao(3, 6, '上六', '凶', '乘马班如，泣血涟如。', '驾着马车原地回旋，哭泣无声，滴泪涟涟。', '泣血涟如。何可长也?', '泣血，泪尽而继之以血。涟如，犹涟然。形容血泪长流不断。', '', '得此爻者，家道中落，须防损失。做官的须谨防小人的谗言。');

// 4. 蒙卦 (100010)
addYao(4, 1, '初六', '吉', '发蒙，利用刑人，用说桎梏，以往吝。', '启发蒙昧，宜树立典型，以免重蹈覆辙。急于求成，必将后悔。', '利用刑人，以正法也。', '利用刑罚约束人，是为了端正法度。', '', '得此爻者，会得到长辈的帮助而成事。做官的宜以身作则，树立榜样。经商的会得利。');
addYao(4, 2, '九二', '吉', '包蒙，吉。纳妇吉，子克家。', '包容蒙昧，吉利。娶妻吉利，儿子能够成家立业。', '包蒙吉，纳妇吉，子克家，刚柔接也。', '包容蒙昧吉利，娶妻吉利，儿子能够成家立业，因为刚柔相济。', '', '得此爻者，会得到贵人的帮助，万事如意，家道兴隆。做官的会得到上司的提拔，经商的会获利丰厚。');
addYao(4, 3, '六三', '凶', '勿用取女，见金夫，不有躬，无攸利。', '不要娶这个女子，她见到有钱的男子就会失身，没有什么好处。', '勿用取女，行不顺也。', '不要娶这个女子，因为她的行为不合乎正道。', '', '得此爻者，不宜强求，否则会有损失。做官的须防女色之祸，经商的须防被骗。');
addYao(4, 4, '六四', '平', '困蒙，吝。', '困在蒙昧之中，艰难。', '困蒙之吝，独远实也。', '困在蒙昧之中的艰难，因为独自远离了现实。', '', '得此爻者，宜寻求帮助，不可独断独行。做官的须防孤立无援，经商的须防陷入困境。');
addYao(4, 5, '六五', '吉', '童蒙，吉。', '幼稚蒙昧，吉利。', '童蒙之吉，顺以巽也。', '幼稚蒙昧的吉利，因为顺从谦逊。', '', '得此爻者，会得到长辈的爱护和帮助，万事如意。做官的会得到上司的提携，经商的会得到贵人的相助。');
addYao(4, 6, '上九', '平', '击蒙，不利为寇，利御寇。', '攻击蒙昧，不利于做寇盗，有利于防御寇盗。', '利用御寇，上下顺也。', '有利于防御寇盗，因为上下都顺从。', '', '得此爻者，宜守不宜攻，否则会有灾祸。做官的须防外敌入侵，经商的须防强盗抢劫。');

// 5. 需卦 (010111)
addYao(5, 1, '初九', '平', '需于郊，利用恒，无咎。', '在郊外等待，利于保持恒心，没有灾祸。', '需于郊，不犯难行也；利用恒无咎，未失常也。', '在郊外等待，不冒险前行；利于保持恒心没有灾祸，没有失去常态。', '', '得此爻者，宜等待时机，不可急躁。做官的须等待机会，经商的须耐心等待。');
addYao(5, 2, '九二', '吉', '需于沙，小有言，终吉。', '在沙滩上等待，有一些小的言语纷争，最终吉利。', '需于沙，衍在中也；虽小有言，以吉终也。', '在沙滩上等待，内心宽舒；虽然有一些小的言语纷争，最终还是吉利的。', '', '得此爻者，会有一些小的麻烦，但最终会顺利解决。做官的须防小人的谗言，经商的须防口舌之争。');
addYao(5, 3, '九三', '平', '需于泥，致寇至。', '在泥泞中等待，招致寇盗到来。', '需于泥，灾在外也；自我致寇，敬慎不败也。', '在泥泞中等待，灾祸来自外部；自己招致寇盗，谨慎就不会失败。', '', '得此爻者，须谨慎行事，不可大意，否则会有灾祸。做官的须防敌人的攻击，经商的须防强盗抢劫。');
addYao(5, 4, '六四', '平', '需于血，出自穴。', '在血泊中等待，从洞穴中出来。', '需于血，顺以听也。', '在血泊中等待，顺从听从。', '', '得此爻者，会有血光之灾，但最终会化险为夷。做官的须防刑伤之灾，经商的须防意外损失。');
addYao(5, 5, '九五', '吉', '需于酒食，贞吉。', '在酒食中等待，贞卜吉利。', '酒食贞吉，以中正也。', '在酒食中等待，贞卜吉利，因为居中守正。', '', '得此爻者，万事如意，大吉大利，有酒食之乐。做官的会有升迁之喜，经商的会获利丰厚。');
addYao(5, 6, '上六', '平', '入于穴，有不速之客三人来，敬之终吉。', '进入洞穴，有三个不请自来的客人到来，恭敬对待他们最终吉利。', '不速之客来，敬之终吉，虽不当位，未大失也。', '不请自来的客人到来，恭敬对待他们最终吉利，虽然位置不当，但没有大的损失。', '', '得此爻者，会有不速之客到来，须恭敬对待，否则会有麻烦。做官的须防不速之客，经商的须防意外之客。');

// 6. 讼卦 (111010)
addYao(6, 1, '初六', '平', '不永所事，小有言，终吉。', '不长久纠缠于所做的事情，有一些小的言语纷争，最终吉利。', '不永所事，讼不可长也；虽小有言，其辩明也。', '不长久纠缠于所做的事情，诉讼不可以长久；虽然有一些小的言语纷争，但辩明了是非。', '', '得此爻者，不宜长久纠缠，否则会有麻烦。做官的须防诉讼缠身，经商的须防纠纷不断。');
addYao(6, 2, '九二', '平', '不克讼，归而逋，其邑人三百户无眚。', '诉讼没有取胜，回去后逃跑了，他邑中的三百户人家没有灾祸。', '不克讼，归逋窜也；自下讼上，患至掇也。', '诉讼没有取胜，回去后逃跑了；从下面告上面，祸患会自己找上门来。', '', '得此爻者，宜退让，不可争讼，否则会有灾祸。做官的须防官司缠身，经商的须防败诉。');
addYao(6, 3, '六三', '凶', '食旧德，贞厉，终吉。或从王事，无成。', '安享旧日的恩德，贞卜危险，最终吉利。或者跟从君王做事，没有成就。', '食旧德，从上吉也。', '安享旧日的恩德，顺从上面的就吉利。', '', '得此爻者，宜安享旧日的成果，不可强求。做官的须防职位不稳，经商的须防亏损。');
addYao(6, 4, '九四', '平', '不克讼，复即命，渝安贞，吉。', '诉讼没有取胜，回复到命令，改变态度保持贞正，吉利。', '复即命渝安贞，不失也。', '回复到命令，改变态度保持贞正，没有失去什么。', '', '得此爻者，宜改变态度，保持贞正，否则会有灾祸。做官的须防违抗命令，经商的须防固执己见。');
addYao(6, 5, '九五', '吉', '讼，元吉。', '诉讼，大吉大利。', '讼元吉，以中正也。', '诉讼大吉大利，因为居中守正。', '', '得此爻者，诉讼会取得胜利，大吉大利。做官的会胜诉，经商的会打赢官司。');
addYao(6, 6, '上九', '凶', '或锡之鞶带，终朝三褫之。', '或者赐予官印绶带，但一天之内三次被剥夺。', '以讼受服，亦不足敬也。', '因为诉讼而得到官职，也不值得尊敬。', '', '得此爻者，须防功过相抵，不宜争讼。做官的须防官职被剥夺，经商的须防得失无常。');

// 7. 师卦 (000010)
addYao(7, 1, '初六', '平', '师出以律，否臧凶。', '军队出征必须遵守纪律，否则会有凶险。', '师出以律，失律凶也。', '军队出征必须遵守纪律，失去纪律就会有凶险。', '', '得此爻者，须遵守纪律，否则会有灾祸。做官的须防军纪不严，经商的须防管理混乱。');
addYao(7, 2, '九二', '吉', '在师中，吉，无咎。王三锡命。', '在军队中，吉利，没有灾祸。君王三次赐予命令。', '在师中吉，承天宠也；王三锡命，怀万邦也。', '在军队中吉利，承受上天的宠爱；君王三次赐予命令，安抚万国。', '', '得此爻者，会得到上司的重用，万事如意。做官的会得到君王的赏赐，经商的会得到贵人的帮助。');
addYao(7, 3, '六三', '凶', '师或舆尸，凶。', '军队可能会载着尸体回来，凶险。', '师或舆尸，大无功也。', '军队载着尸体回来，说明打了大败仗。', '', '得此爻者，须防大败，不宜出兵。做官的须防战败，经商的须防亏本。');
addYao(7, 4, '六四', '平', '师左次，无咎。', '军队驻扎在左边，没有灾祸。', '左次无咎，未失常也。', '驻扎在左边没有灾祸，没有失去常态。', '', '得此爻者，宜退守，不可冒进。做官的须防冒进失利，经商的须防冒险失败。');
addYao(7, 5, '六五', '吉', '田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。', '田野里有禽兽，利于捕捉，没有灾祸。长子率领军队，弟子载着尸体回来，贞卜凶险。', '长子帅师，以中行也；弟子舆尸，使不当也。', '长子率领军队，因为行为中正；弟子载着尸体回来，因为使用不当。', '', '得此爻者，须任用得当，否则会有灾祸。做官的须防用人不当，经商的须防委托非人。');
addYao(7, 6, '上六', '平', '大君有命，开国承家，小人勿用。', '君王有命令，分封诸侯建立国家，小人不要任用。', '大君有命，以正功也；小人勿用，必乱邦也。', '君王有命令，用来评定功劳；小人不要任用，否则一定会扰乱国家。', '', '得此爻者，会得到封赏，但须防小人。做官的会得到升迁，经商的会得到利益。');

// 8. 比卦 (010000)
addYao(8, 1, '初六', '吉', '有孚比之，无咎。有孚盈缶，终来有它吉。', '有诚信去亲近，没有灾祸。诚信像装满酒的罐子一样，终究会有其他的吉利。', '比之初六，有它吉也。', '比卦的初六，有其他的吉利。', '', '得此爻者，会得到朋友的帮助，万事如意。做官的会得到同僚的支持，经商的会得到伙伴的相助。');
addYao(8, 2, '六二', '吉', '比之自内，贞吉。', '从内部去亲近，贞卜吉利。', '比之自内，不自失也。', '从内部去亲近，没有失去自己。', '', '得此爻者，会得到内部的支持，万事顺遂。做官的会得到下属的拥护，经商的会得到内部的合作。');
addYao(8, 3, '六三', '凶', '比之匪人。', '亲近了不应该亲近的人。', '比之匪人，不亦伤乎？', '亲近了不应该亲近的人，不也是一种伤害吗？', '', '得此爻者，须防交友不慎，否则会有灾祸。做官的须防小人，经商的须防损友。');
addYao(8, 4, '六四', '平', '外比之，贞吉。', '向外去亲近，贞卜吉利。', '外比于贤，以从上也。', '向外亲近贤能的人，以顺从上面的人。', '', '得此爻者，会得到外部的帮助，万事顺利。做官的会得到上司的提携，经商的会得到外部的合作。');
addYao(8, 5, '九五', '吉', '显比，王用三驱，失前禽，邑人不诫，吉。', '明显地亲近，君王用三面驱赶的方式打猎，放走前面的禽兽，邑中的人不警戒，吉利。', '显比之吉，位正中也；舍逆取顺，失前禽也；邑人不诫，上使中也。', '明显亲近的吉利，因为位置居中；舍弃叛逆的，选取顺从的，放走前面的禽兽；邑中的人不警戒，因为上面的人使用中道。', '', '得此爻者，会得到君王的宠爱，万事如意。做官的会得到君王的重用，经商的会得到贵人的帮助。');
addYao(8, 6, '上六', '平', '比之无首，凶。', '亲近却没有首领，凶险。', '比之无首，无所终也。', '亲近却没有首领，没有好的结局。', '', '得此爻者，须防群龙无首，否则会有灾祸。做官的须防领导不力，经商的须防组织混乱。');

// 9. 小畜卦 (110111)
addYao(9, 1, '初九', '平', '复自道，何其咎，吉。', '从自己的道路返回，有什么灾祸呢，吉利。', '复自道，其义吉也。', '从自己的道路返回，从道义上说是吉利的。', '', '得此爻者，宜走正道，不可偏离。做官的须防误入歧途，经商的须防偏离正轨。');
addYao(9, 2, '九二', '平', '牵复，吉。', '牵着返回，吉利。', '牵复在中，亦不自失也。', '在中间牵着返回，也没有失去自己。', '', '得此爻者，会得到朋友的帮助而返回正道，万事顺遂。做官的会得到同僚的帮助，经商的会得到伙伴的相助。');
addYao(9, 3, '九三', '平', '舆说辐，夫妻反目。', '车轮的辐条脱落，夫妻反目。', '夫妻反目，不能正室也。', '夫妻反目，不能端正家庭。', '', '得此爻者，须防家庭不和，否则会有麻烦。做官的须防夫妻失和，经商的须防合伙人反目。');
addYao(9, 4, '六四', '平', '有孚，血去惕出，无咎。', '有诚信，忧虑消失，警惕出现，没有灾祸。', '有孚惕出，上合志也。', '有诚信，警惕出现，与上面的人意志相合。', '', '得此爻者，会消除忧虑，保持警惕，没有灾祸。做官的须防忧虑缠身，经商的须防警惕不足。');
addYao(9, 5, '九五', '吉', '有孚挛如，富以其邻。', '有诚信而紧密相连，富裕了邻居。', '有孚挛如，不独富也。', '有诚信而紧密相连，不独自富裕。', '', '得此爻者，会与邻居共同富裕，万事如意。做官的会与同僚共同发展，经商的会与伙伴共同获利。');
addYao(9, 6, '上九', '平', '既雨既处，尚德载，妇贞厉，月几望，君子征凶。', '已经下雨了，已经停止了，崇尚道德承载，妇人贞卜危险，月亮接近满月，君子出征凶险。', '既雨既处，德积载也；君子征凶，有所疑也。', '已经下雨了，已经停止了，道德积累承载；君子出征凶险，因为有所疑虑。', '', '得此爻者，宜守不宜进，否则会有灾祸。做官的须防出征不利，经商的须防冒险失败。');

// 10. 履卦 (111011)
addYao(10, 1, '初九', '平', '素履往，无咎。', '穿着朴素的鞋子前往，没有灾祸。', '素履之往，独行愿也。', '穿着朴素的鞋子前往，独自实现自己的愿望。', '', '得此爻者，宜朴素行事，不可奢华。做官的须防奢华过度，经商的须防铺张浪费。');
addYao(10, 2, '九二', '吉', '履道坦坦，幽人贞吉。', '行走在平坦的道路上，隐士贞卜吉利。', '幽人贞吉，中不自乱也。', '隐士贞卜吉利，内心不会自我扰乱。', '', '得此爻者，会行走在平坦的道路上，万事顺遂。做官的会仕途平坦，经商的会道路顺利。');
addYao(10, 3, '六三', '平', '眇能视，跛能履，履虎尾，咥人，凶。武人为于大君。', '眼睛瞎了一只还能看，腿瘸了还能走，踩到了老虎的尾巴，老虎咬人，凶险。武人做了君王。', '眇能视，不足以有明也；跛能履，不足以与行也；咥人之凶，位不当也；武人为于大君，志刚也。', '眼睛瞎了一只还能看，不足以看得清楚；腿瘸了还能走，不足以一起行走；老虎咬人的凶险，因为位置不当；武人做了君王，因为意志刚强。', '', '得此爻者，须防力不从心，否则会有灾祸。做官的须防能力不足，经商的须防力不胜任。');
addYao(10, 4, '九四', '平', '履虎尾，愬愬，终吉。', '踩到了老虎的尾巴，恐惧害怕，最终吉利。', '愬愬终吉，志行也。', '恐惧害怕最终吉利，因为意志得以实行。', '', '得此爻者，虽然会遇到危险，但最终会化险为夷。做官的须防危险，经商的须防风险。');
addYao(10, 5, '九五', '吉', '夬履，贞厉。', '决断地行走，贞卜危险。', '夬履贞厉，位正当也。', '决断地行走，贞卜危险，因为位置正当。', '', '得此爻者，须果断行事，但须防危险。做官的须防决断失误，经商的须防决策失误。');
addYao(10, 6, '上九', '平', '视履考祥，其旋元吉。', '回顾走过的道路考察吉凶，返回原地大吉大利。', '元吉在上，大有庆也。', '大吉大利在上面，有很大的喜庆。', '', '得此爻者，宜回顾过去，总结经验，返回原地会大吉大利。做官的须防失误，经商的须防失败。');

// 11. 泰卦 (000111)
addYao(11, 1, '初九', '吉', '拔茅，茹以其汇，征吉。', '连根拔掉茅草，及其同类。征伐敌人，吉利。', '拔茅征吉，志在外也。', '连根拔掉茅草，彻底征服敌人，吉利，说明志在讨伐敌国。', '', '得此爻者，志同合谋，财利日增。做官的会逐步升迁。');
addYao(11, 2, '九二', '吉', '包荒，用冯河，不遐遗，朋亡，得尚于中行。', '用挖空的瓠瓜绑在身上渡河，不至于沉没。钱币丢失了，在半路上得到别人的帮助。', '包荒，得尚于中行，以光大也。', '其人度量弘大，深得同路人的赏识，这是由于他光明正大呀。', '', '得此爻者，会有好运，必遇尊贵，但要防长上有损，言语有伤。做官的会身居高位，功名显达。');
addYao(11, 3, '九三', '平', '无平不陂，无往不复。艰贞无咎。勿恤其孚，于食有福。', '平地终将变成坡地，离去必定复返。卜问艰难之事，爻象显示必能渡过难关，不要担心被人虏去，而且在饮食上尚有口福。', '无往不复，天地际也。', '离去必定复返，这是天地间的法则。', '', '得此爻者，须谨慎自持，宜保守，则安，不然会犯小人，事事遇阻。做官的会比较艰难，须防小人和别人的妒忌。');
addYao(11, 4, '六四', '平', '翩翩不富以其邻，不戒以孚。', '巧言欺人，将给邻邑带来灾难;不加警戒，即将遇难被虏。', '翩翩不富，皆失实也;不戒以孚，中心愿也。', '巧言欺人，祸及邻人，是说同受损失。不加警戒，遇难被虏，这是因为心地太忠厚了。', '', '得此爻者，营谋失利，退守可平安。做官的进取难成，宜退守。');
addYao(11, 5, '六五', '吉', '帝乙归妹，以祉元吉。', '殷帝乙嫁女于周文王，因而得福，大吉大利。', '以祉元吉，中以行愿也。', '得福大吉，因为六五之爻居上卦中位，像人行事得中正之道，所行必遂。', '', '得此爻者，会得到别人的赏识和抬举，或结婚生子，幸福安乐。做官的或能升迁，或有喜事。');
addYao(11, 6, '上六', '凶', '城复于隍，勿用师。自邑告命，贞吝。', '城墙攻破倒塌在护城壕里。"停止进攻"，从邑中传来命令。卜问得不祥之兆。', '城复于隍，其命乱也。', '城墙攻破倒塌在护城壕里(本应乘势攻击，反命停止进攻)，这是邑中传来的命令错乱了。', '', '得此爻者，会有破损，有疾病，谨慎厚道者可免祸。做官的会被贬职。');

// 12. 否卦 (111000)
addYao(12, 1, '初六', '平', '拔茅，茹以其汇，贞吉，亨。', '连根拔掉茅草，及其同类，占得此爻则吉利，亨通。', '拔茅贞吉，志在君也。', '连根拔掉茅草，占得此爻吉利，比喻其志在清理君侧，为国尽忠。', '', '得此爻者，宜守旧，小人得势之时，爻辞虽好，但须谨防小人牵连之事。做官的受职者待缺，当权者防扰。');
addYao(12, 2, '六二', '平', '包承，小人吉;大人否，亨。', '厨中有肉，这对老百姓来说是吉利，对贵族来说并不是通泰的表现。', '大人否，享，不乱群也。', '贵族身处窘境，则能心怀惩戒，使其安守本分。', '', '得此爻者，宜忍耐，宽容待人，不然会生是非。做官的宜低调行事。');
addYao(12, 3, '六三', '凶', '包羞。', '厨中有美味。', '包羞，位不当也。', '心怀羞愧，因为才德不称其位。', '', '得此爻者，须防是非争诉之扰。做官的会退休离职。');
addYao(12, 4, '九四', '吉', '有命无咎，畴离祉。', '君王有赏赐之命，没有灾害，谁能得到赏赐呢?', '有命无咎，志行也。', '君王有赏赐之命，没有灾害，说明君王论功行赏，臣下尽职效力，各行其志。', '', '得此爻者，家产日增，吉庆安乐。做官的会得到朋友和同僚之助，或升迁，或进财。');
addYao(12, 5, '九五', '吉', '休否，大人吉;其亡其亡，系于苞桑。', '警戒覆亡，贵族王公如此存心则吉利。危险呵，危险，国家命运好像系在柔弱的苞草、桑枝上一样。', '大人之吉，位正当也。', '九五爻辞讲贵族王公安不忘危则吉利。因为九五之爻居上卦中位，像其人忧国忧君，才德正当其位。', '', '得此爻者，旧祸已去，好运将至，诸事皆吉。做官的会身居重位。');
addYao(12, 6, '上九', '平', '倾否，先否后喜。', '短暂的恶运，先遇恶运后交好运。', '否终则倾，何可长也?', '恶运快终了，好运岂迢遥。命运交变之际，什么力量可以制止呢?', '', '得此爻者，将会转好运，久困者利可期，久讼者讼事解。做官的失职者复职，闲缺者会走马上任。');

// 13. 同人卦 (111101)
addYao(13, 1, '初九', '平', '同人于门，无咎。', '聚集大众于王门，将行大事，没有灾祸。', '出门同人，又谁咎也?', '君王走出王门与国人打成一片，谁又会遭受灾祸呢?', '', '得此爻者，能与人合伙经营获利，或出家远行，或修造门户，或在他处学习。做官的或会受到重用，或有升迁之机。');
addYao(13, 2, '六二', '凶', '同人于宗，吝。', '聚同族于宗庙，卜祷凶吉，因为面临艰难。', '同人于宗，吝道也。', '仅仅聚同族于宗庙，这是狭隘的宗法原则。', '', '得此爻者，事多不定，与宗人朋友多不和，相互多猜忌，面和心不合，容易起是非。做官的没有升迁之机，需耐心等待。');
addYao(13, 3, '九三', '凶', '伏戎于莽，升其高陵，三岁不兴。', '将军队隐蔽在深山密林，并且占领了制高点，但长时期不能取胜。', '伏戎于莽，敌刚也，三岁不兴，安行也。', '将军队隐蔽在深山密林，因为敌人太强大。长时期不能取胜，怎能有所作为呢?', '', '得此爻者，或有丧亲，或有诉讼打官司之患。做官的须防被免职之忧。');
addYao(13, 4, '九四', '平', '乘其墉，弗克攻，吉。', '爬上了敌人的城墙，城还没有攻下来，继续攻打才能获胜。', '乘其墉，义弗克也，其吉，则困而反则也。', '爬上了敌人的城墙，从道义上讲应该停士攻城。之所以继续攻打为吉利，因为困守之敌可能逞其狡诈。', '', '得此爻者，亲友之间会互相猜忌，荣中有辱，结果会好些，凡事须多加提防则可吉祥。做官的若能兢兢业业，则有提拔之机遇，或会受到表彰。');
addYao(13, 5, '九五', '平', '同人，先号啕而后笑，大师克相遇。', '聚集起来的大众先哭号后欢笑，因为大军及时增援，大获胜仗。', '同人之先，以中直也。大师相遇，言相克也。', '聚集起来的大众之所以先哭后笑(战斗转败为胜)，因为筮遇此爻，九五居上卦之中位，像人得贞正之道，势必化凶为吉。大军会师，是说我军压倒了敌人。', '', '得此爻者，先难后易，是非不一。做官的会先贬后升。');
addYao(13, 6, '上九', '平', '同人于郊，无悔。', '聚众于郊外，致祭于神灵祝贺胜利，自然没有悔咎。', '同人于郊，志未得也。', '聚众于郊外，援助不广，尚不得行其志。', '', '得此爻者，宜守常，不宜激进。做官的则多有出差的机会。');

// 14. 大有卦 (101111)
addYao(14, 1, '初九', '平', '无交害，匪咎;艰则无咎。', '不要彼此侵害，即没有灾祸，既使处于艰难之中，也没有灾祸。', '大有初九，无交害也。', '大有初九爻辞说，不要彼此侵害。', '', '得此爻者，心绪不定，小人欺凌，很是艰辛，长辈或有灾难。做官的须急流勇退，不可贪婪荣华富贵。');
addYao(14, 2, '九二', '吉', '大车以载，有攸往，无咎。', '用大车装物载人，有明确的目的地，没有灾祸。', '大车以载，积中不败也。', '用大车装物载人，物积于车中不会散失。', '', '得此爻者，营谋得利，财利丰厚，但不利于老人的健康。做官的闲职者会受到重用。');
addYao(14, 3, '九三', '平', '公用，亨于天子，小人弗克。', '天子宴请公侯。小人则不能参与。', '公用亨于天子，小人害也。', '天子宴请公侯，(小人不能参与)因为小人参与国政，将是国家的祸害。', '', '得此爻者，有灾难，举步维艰，勿近小人。做官的会受到重任，读书人会取得很好的成绩。');
addYao(14, 4, '九四', '平', '匪其彭，无咎。', '用曝晒男巫来求雨，旱情严重，但没有灾祸。', '匪其彭，无咎，明辩晰也。', '反对坏人坏事没有灾祸，因为明于考察辨析。', '', '得此爻者，宜守常，则可避免伤害，眼睛方面或会出现病症。做官的须安于现状，不可激进，则可免祸。');
addYao(14, 5, '六五', '吉', '厥孚交如，威如，吉。', '来犯之敌被紧紧捆绑，严厉惩罚，吉利。', '厥孚交如，信以发志也;威如之吉，易而无备也。', '其人诚信坦白，因为他以诚信来表现自己的志向。威服众人之所以吉利，因为众人敬畏，则能平安而不困惫。', '', '得此爻者，须相时而动，切不可骄傲自负，以免自取其祸。做官的宜退不宜进。');
addYao(14, 6, '上九', '吉', '自天右之，吉无不利。', '上天保右，吉利，无所不顺利。', '大有上吉，自天右也。', '大有是大吉大利之卦，因为得到上天的保右。', '', '得此爻者，得到祖上之庇佑，一路好运。做官的以及读书人会进职成名。');

// 15. 谦卦 (001000)
addYao(15, 1, '初六', '平', '谦谦君子，用涉大川，吉。', '谦让，再谦让，这才是君子的风度。具有这种品德，即使冒险涉水过河，也是吉利的。', '谦谦君子，卑以自牧也。', '十分谦让的君子，就是从谦让入手进行自我修养。', '', '得此爻者，宜远行或出游，出外做生意会发财。做官的须退守，不宜与人争利，出差的机会会多。');
addYao(15, 2, '六二', '吉', '鸣谦，贞吉。', '明智而谦让，卜问得吉兆。', '鸣谦贞吉，中心得也。', '明智而谦让，心正而吉利，因为六二之爻居下卦中位，像人守中正之道。', '', '得此爻者，不宜轻举妄动，宜退守。做官的会升迁，读书人会进取成名。');
addYao(15, 3, '九三', '吉', '劳谦，君子有终，吉。', '勤劳而谦让，这样的人将有好结果，凡事吉利。', '劳谦君子，万民服也。', '勤劳而谦让的君子，万民敬服。', '', '得此爻者，营谋得利，但会劳心劳力。做官的会高升。');
addYao(15, 4, '六四', '吉', '无不利，撝谦。', '无所不利，只要奋勇直前而又谦虚谨慎。', '无不利，撝谦，不违则也。', '无所不利，只要奋勇直前而又谦虚谨慎，因为这样才不会违犯法则。', '', '得此爻者，无所不通，但做官的、读书人及商人宜固守退让，太盛则有过。');
addYao(15, 5, '六五', '平', '不富以其邻，利用侵伐，无不利。', '贫穷是由于敌国的侵掠，应该对之讨伐，无所不利。', '利用侵伐，征不服也。', '筮遇此爻有利于征战讨伐，因为是征讨不服从王命的人。', '', '得此爻者，会得到贵人的帮助而成事，会获得利益，但须谨防生出祸端，与人争诉。当官的会文武兼用，利于进取。读书人会有金榜题名之机会。');
addYao(15, 6, '上六', '平', '鸣谦，利用行师，征邑国。', '明智而谦让，出兵征伐邑国自然获胜。', '鸣谦，志未得也;可用行师，征邑国也。', '明智而谦让，尚不能感化邑国得行其志，就可以出兵征讨邑国。', '', '得此爻者，有争诉之扰，但会不辨自明。做官的须修德养身，进取有望。');

// 16. 豫卦 (000100)
addYao(16, 1, '初六', '凶', '鸣豫，凶。', '津津乐道于荒淫享乐，凶险。', '初六鸣豫，志穷凶也。', '初六爻辞讲，津津乐道于荒淫享乐，其人意志必消退，身名必败裂。', '', '得此爻者，不顺，有口舌之争，前进有阻力。做官的不要得意忘形，须谨慎，以免生祸。读书人则可能会一鸣惊人。');
addYao(16, 2, '六二', '吉', '介于石，不终日，贞吉。', '夹在石缝中，幸而不到一天就被人救出。卜问得吉兆。', '不终日，贞吉，以中正也。', '磨难不足一日即解除，卜问得吉兆，因为六二之爻居下卦中位，像人得中正之道。', '', '得此爻者，会获利。做官的宜急流勇退，读书人有成名之机。');
addYao(16, 3, '六三', '凶', '盱豫，悔。 迟有悔。', '懒散游乐，将招致后悔;再加上懈怠大意，那就后悔莫及。', '盱豫有悔，位不当也。', '懒散游乐，将招致后悔，因为六三之爻居于阳位，是处置不当，像人之行事与所处地位不相称。', '', '得此爻者，投机取巧，是非不一。');
addYao(16, 4, '九四', '吉', '由豫，大有得，勿疑，朋盍簪。', '田猎取乐，大获鸟兽。筮遇此爻，勿疑友人多嘴而谗己。', '由豫大有得。志大行也。', '田猎取乐，大获鸟兽，说明猎获甚多，如愿以偿。', '', '得此爻者，进取成名，经营获利。做官的会得到知己，进取有望。');
addYao(16, 5, '六五', '凶', '贞疾，恒不死。', '卜问疾病，长时间内不会死去。', '六五贞疾，乘刚也。恒不死，中未亡也。', '六五爻辞讲患病，因为六五阴爻居于九四阳爻之上，犯了柔乘刚之象。"长时间不会死去"，因为六五之爻居于上卦中位，正当不死之象。', '', '得此爻者，多心事，有灾难，或有腹疾。做官的多洋洋得意，持恩固宠，难免有失。');
addYao(16, 6, '上六', '平', '冥豫，成有渝，无咎。', '末日将至尚且享乐，已成之事也将毁败。', '冥豫在上，何可长也?', '末日将至尚且享乐，以此居上位，怎能长久。', '', '得此爻者，因为心气太高，会有诉争之扰，但若能改过自新，心态平和，则不会有过失。做官的会有贪污之嫌，须明哲保身。');

// 17. 随卦 (011001)
addYao(17, 1, '初九', '吉', '官有渝，贞吉。 出门交有功。', '馆舍时里发生事故，筮遇此爻则吉，出门同行都得好处。', '官有渝，从正吉也;出门交有功，不失也。', '官吏把事情办坏了，归从正道则吉利。出门同行都得好处，这是不失正道的缘故。', '', '得此爻者，多获利。做官的正当好运，有升迁之机。');
addYao(17, 2, '六二', '凶', '系小子，失丈夫。', '抓住了未成年的奴隶，跑了成年的奴隶。', '系小子，弗兼与也。', '抓住了小的，跑了大的，意思是两者不能兼得。', '', '得此爻者，不安宁，或受小人的暗算，是非不断。当官的宜退守，进取者要有自知之明。');
addYao(17, 3, '六三', '平', '系丈夫，失小子。随有求，得，利居贞。', '抓住了成年奴隶，跑了未成年奴隶。希望无失不如现得。筮遇此爻，卜问居处则吉利。', '系丈夫，志舍下也。', '抓了大的，跑了小的，其志在于追逐大的，舍弃小的。', '', '得此爻者，营谋遂意，但宜走正道，才能得利。做官的会得到保举而升迁有望。');
addYao(17, 4, '九四', '平', '随有获，贞凶。有孚，在道以明，何咎?', '追名逐利，贪多务获，卜问得凶兆。押送俘虏上路，明于约束，没有灾难。', '随有获，其义凶也。有孚在道，明功也。', '追名逐利，贪多务获，这种人遭遇凶险是应该的。谨守信用，严守正道，这是明察事功的结果。', '', '得此爻者，会得到好人的抬举，化凶为吉。做官的会身居要职，努力进取者可成事，可获得名利。');
addYao(17, 5, '九五', '吉', '孚于嘉，吉。', '俘虏了不少嘉人，吉利。', '孚于嘉吉，位正中也。', '信守中正之道，诸事吉利，因为九五之爻居上卦中位，像人守中正之道。', '', '得此爻者，营谋遂意，多喜庆之事，做官的会升职，或多喜事。');
addYao(17, 6, '上六', '凶', '拘系之，乃从维之;王用亨于西山。', '将俘虏拘禁起来，紧紧捆绑，周文王将他们作为人牲在西山祭祀神灵。', '拘系之，上穷也。', '被捆绑拘禁，因为上六居一卦之尽头，像人处于穷困之境地。', '', '得此爻者，苦难多多，不很如意，重病者会有生命之忧。做官的须防止小人的谗言。');

// 18. 蛊卦 (100110)
addYao(18, 1, '初六', '吉', '干父之蛊，有子，考无咎。厉，终吉。', '继承父业，有一个孝顺的儿子，固然没有灾害，即使遇到危险，最后乃吉利。', '干父之蛊，意承考也。', '继承父业，意思是继承其父遗志。', '', '得此爻者，会得到祖先的庇佑，营谋遂意。做官的会受到重任，改革创新。');
addYao(18, 2, '九二', '平', '乾母之蛊，不可贞。', '继承母业，则吉凶不可卜问。', '乾母之蛊，得中道也。', '继承母业，九二处下卦中位，爻象显示其人得中正之道。', '', '得此爻者，改旧从新，则会如意。女命勤俭持家，性忠直者多福。');
addYao(18, 3, '九三', '凶', '干父之蛊，小有悔，无大咎。', '继承父业，即使稍有过错，也不会出大问题。', '干父之蛊，终无咎也。', '继承父业，最终不会遭逢灾难。', '', '得此爻者，躁进者有失，不听信谗言者则无难。');
addYao(18, 4, '六四', '凶', '裕父之蛊，往见吝。', '光大父业，施行起来困难重重。', '裕父之蛊，往未得也。', '光大父业(困难重重)，施行之中未尽得当。', '', '得此爻者，事事见忧，有足疾。');
addYao(18, 5, '六五', '吉', '干父之蛊，用誉。', '继承父业，博得了赞誉。', '干父之蛊，承以德也。', '继承父业而博得了赞誉，因为继承了其父的美好品德。', '', '得此爻者，多喜庆之事，家中或进人口。做官的进取有望，名誉远播。');
addYao(18, 6, '上九', '平', '不事王侯，高尚其事。', '不服务于王侯，因为其人看重自身价值。', '不事王侯，志可则也。', '不服务于王侯，这种志趣可以效法。', '', '得此爻者，宜守旧，好运者，多遇尊贵，能获得提拔。做官的宜退守，或告休。');

// 19. 临卦 (000011)
addYao(19, 1, '初九', '吉', '咸临，贞吉。', '以感化之道治民，贞卜得吉兆。', '咸临贞吉，志行正也。', '以感化之道治民，贞卜得吉兆，说明施政者志向端正。', '', '得此爻者，营谋得利，与人合作更佳。做官的会亲民，得到百姓的爱戴。');
addYao(19, 2, '九二', '吉', '咸临，吉无不利。', '以感化之道治民，吉利，无所不利。', '咸临吉无不利，未顺命也。', '以感化之道治民，吉利，无所不利，说明百姓尚未完全顺服。', '', '得此爻者，万事如意，大吉大利，有贵人相助。做官的会得到上司的赏识。');
addYao(19, 3, '六三', '平', '甘临，无攸利。既忧之，无咎。', '以甜言蜜语治民，没有好处。如果能忧虑此事，则可无灾祸。', '甘临，位不当也。既忧之，咎不长也。', '以甜言蜜语治民，因为位置不当。如果能忧虑此事，灾祸不会长久。', '', '得此爻者，宜谨慎行事，不可靠甜言蜜语，否则会有损失。做官的须防花言巧语，经商的须防虚假广告。');
addYao(19, 4, '六四', '平', '至临，无咎。', '亲自临视，没有灾祸。', '至临无咎，位当也。', '亲自临视，没有灾祸，因为位置恰当。', '', '得此爻者，会得到上司的亲自关照，万事顺遂。做官的会得到上司的提携，经商的会得到贵人的帮助。');
addYao(19, 5, '六五', '吉', '知临，大君之宜，吉。', '以智慧治民，这是君王适宜的做法，吉利。', '大君之宜，行中之谓也。', '君王适宜的做法，就是行为中正。', '', '得此爻者，会得到君王的赏识，万事如意。做官的会得到君王的重用，经商的会得到贵人的帮助。');
addYao(19, 6, '上六', '平', '敦临，吉，无咎。', '以敦厚之道治民，吉利，没有灾祸。', '敦临之吉，志在内也。', '以敦厚之道治民，吉利，因为志向在于内心。', '', '得此爻者，宜敦厚行事，不可刻薄，否则会有灾祸。做官的须敦厚待人，经商的须诚信经营。');

// 20. 观卦 (110000)
addYao(20, 1, '初六', '平', '童观，小人无咎，君子吝。', '幼稚地观察，小人没有灾祸，君子则有困难。', '初六童观，小人道也。', '初六的幼稚观察，是小人的做法。', '', '得此爻者，须防幼稚行事，否则会有困难。做官的须防幼稚决策，经商的须防幼稚判断。');
addYao(20, 2, '六二', '平', '窥观，利女贞。', '从门缝里观察，利于女子的贞卜。', '窥观女贞，亦可丑也。', '从门缝里观察，对于女子的贞洁来说，也是一种丑行。', '', '得此爻者，宜谨慎观察，不可偏听偏信。做官的须防片面观察，经商的须防盲目判断。');
addYao(20, 3, '六三', '凶', '观我生，进退。', '观察自己的生活，决定进退。', '观我生进退，未失道也。', '观察自己的生活，决定进退，没有失去正道。', '', '得此爻者，须谨慎进退，不可盲目行动。做官的须防进退失据，经商的须防盲目投资。');
addYao(20, 4, '六四', '平', '观国之光，利用宾于王。', '观察国家的光辉，利于做君王的宾客。', '观国之光，尚宾也。', '观察国家的光辉，崇尚做宾客。', '', '得此爻者，会得到君王的赏识，成为君王的宾客。做官的会得到君王的重用，经商的会得到贵人的帮助。');
addYao(20, 5, '九五', '吉', '观我生，君子无咎。', '观察自己的生活，君子没有灾祸。', '观我生君子，观民也。', '观察自己的生活，君子观察的是民众。', '', '得此爻者，会得到民众的拥护，万事如意。做官的会得到民众的支持，经商的会得到顾客的信任。');
addYao(20, 6, '上九', '平', '观其生，君子无咎。', '观察他人的生活，君子没有灾祸。', '观其生，志未平也。', '观察他人的生活，志向尚未平静。', '', '得此爻者，须观察他人，不可自以为是。做官的须防刚愎自用，经商的须防盲目自信。');

// 21. 噬嗑卦 (101001)
addYao(21, 1, '初九', '平', '屦校灭趾，无咎。', '脚上戴着刑具，脚趾被遮住了，没有灾祸。', '屦校灭趾，不行也。', '脚上戴着刑具，脚趾被遮住了，不能行走。', '', '得此爻者，会受到小的惩罚，但没有大的灾祸。做官的须防小的过失，经商的须防小的错误。');
addYao(21, 2, '六二', '吉', '噬肤灭鼻，无咎。', '咬肥肉，鼻子被遮住了，没有灾祸。', '噬肤灭鼻，乘刚也。', '咬肥肉，鼻子被遮住了，因为乘凌于刚爻之上。', '', '得此爻者，会得到好处，但须防贪婪。做官的须防贪婪受贿，经商的须防贪得无厌。');
addYao(21, 3, '六三', '凶', '噬腊肉，遇毒，小吝，无咎。', '咬腊肉，遇到了毒物，有小的困难，没有灾祸。', '遇毒，位不当也。', '遇到了毒物，因为位置不当。', '', '得此爻者，须防中毒，否则会有小的困难。做官的须防小人的毒害，经商的须防假冒伪劣。');
addYao(21, 4, '九四', '平', '噬乾胏，得金矢，利艰贞，吉。', '咬干骨头，得到了金箭头，利于艰难的贞卜，吉利。', '利艰贞吉，未光也。', '利于艰难的贞卜，吉利，但尚未发扬光大。', '', '得此爻者，会遇到困难，但最终会得到好处。做官的须防艰难险阻，经商的须防困难重重。');
addYao(21, 5, '六五', '吉', '噬乾肉，得黄金，贞厉，无咎。', '咬干肉，得到了黄金，贞卜危险，没有灾祸。', '贞厉无咎，得当也。', '贞卜危险，没有灾祸，因为得当。', '', '得此爻者，会得到财富，但须防危险。做官的须防贪污受贿，经商的须防冒险投资。');
addYao(21, 6, '上九', '平', '何校灭耳，凶。', '肩上扛着刑具，耳朵被遮住了，凶险。', '何校灭耳，聪不明也。', '肩上扛着刑具，耳朵被遮住了，听觉不明。', '', '得此爻者，会受到大的惩罚，凶险。做官的须防重大过失，经商的须防重大错误。');

// 22. 贲卦 (100101)
addYao(22, 1, '初九', '平', '贲其趾，舍车而徒。', '脚穿花鞋，舍车不乘，徒步而行。', '舍车而徒，义弗乘也。', '舍车不乘，徒步而行，为显示鞋子之美丽，理应不乘车。', '', '得此爻者，多奔波，静凶动吉。做官的须防退职之患。');
addYao(22, 2, '六二', '平', '贲其须。', '修饰自己的胡须。', '贲其须，与上兴也。', '修饰自己的胡须，说明老人不服老，帮助君王振兴国家。', '', '得此爻者，得人提拔，好运可期，但也要相时而动，不可随性而为，以免遭难。做官的会因人成事，升迁有望。');
addYao(22, 3, '九三', '吉', '贲如，濡如，永贞吉。', '奔跑向前，汗流浃背。卜问长时期的凶吉而得吉兆。', '永贞之吉，终莫之陵也。', '永远贞正，必吉利，因为决没有人侵凌正人君子。', '', '得此爻者，好运来到，不必费力，自然荣盛，即使有是非纠纷，也不足为患。做官的与人和睦，能居要职。');
addYao(22, 4, '六四', '平', '贲如，皤如，白马翰如，匪寇婚媾。', '奔跑气吁吁，太阳火辣辣。高头白马，向前飞奔。不是来抢劫，而是来娶亲。', '六四当位疑也。匪寇婚媾，终无尤也。', '六四阴爻居阴位，所处恰当。既知不是来抢劫，而是来娶亲，疑虑冰释，终无灾祸。', '', '得此爻者，先凶后吉，忧中有喜，虽有危险，终得安宁。未婚者，有望成家。做官的先难后易。');
addYao(22, 5, '六五', '吉', '贲于丘园，束帛戋戋。吝，终吉。', '奔向丘园，送上许多布帛，初遇困难，终则顺利。', '六五之吉，有喜也。', '六五爻辞说的吉利，是指有婚姻之喜。', '', '得此爻者，会遇贵人，经营获利，多喜事。做官的闲职者会受到重用，在职者福禄双全。');
addYao(22, 6, '上九', '平', '白贲，无咎。', '送上白底饰以诸色花纹的布帛，不会坏事。', '白贲无咎，上得志也。', '白底的布帛饰以诸色花纹，没有灾祸，因为上九居一卦之首位，像人高高在上，志得意满。', '', '得此爻者，须防好运转凶，家中、亲属有长辈或命终。做官的会升迁。');

// 23. 剥卦 (000001)
addYao(23, 1, '初六', '凶', '剥床以足，蔑贞，凶。', '床足脱落。无须占问，这是凶险之象。', '剥床以足，以灭下也。', '床足脱落，这是自毁根基。', '', '得此爻者，营谋不遂，或有手足之灾，或兄弟不睦，凶则家破身亡。做官的有升迁之机会，但宜见机行事。');
addYao(23, 2, '六二', '凶', '剥床以辨，蔑贞，凶。', '床板脱落。无须占问，这是凶险之象。', '剥床以辨，未有与也。', '床板脱落，这是自毁辅佐。', '', '得此爻者，营谋不遂，或受到小人的侵辱，或受到他人的猜忌。做官的须防被贬职。');
addYao(23, 3, '六三', '平', '剥之，无咎。', '割取邻国邻邑的土地人民，可以无灾祸。', '剥之无咎，失上下也。', '割取邻国邻邑的土地人民，可以无灾祸，因为邻国邻邑的统治者已失去了上下臣民的支持。', '', '得此爻者，难遇知己，生涯不顺，欲求名利，必须创新，此爻像父母妻子或有忧，须谨防。做官的会遇到明主或大官提拔。');
addYao(23, 4, '六四', '凶', '剥床以肤，凶。', '剥取床上的垫席，这是凶险之象。', '剥床以肤，切近灾也。', '剥取床上的垫席，灾祸就在眼前。', '', '得此爻者，时运不佳，危难之时，多有争诉刑克之事。做官的须谨防小人的谗言，以免遭难。');
addYao(23, 5, '六五', '吉', '贯鱼，以宫人宠，无不利。', '宫人依次当夕受宠，无所不利。', '以宫人宠，终无尤也。', '宫人依次当夕受宠，秩序不乱，厚薄均匀，因而终无忧患。', '', '得此爻者，人情和合，营谋得时，家和福生，妇人进财。做官的升高进职，居要位。读书人、学子考试必能考出佳绩。');
addYao(23, 6, '上九', '平', '硕果不食，君子得舆，小人剥庐。', '劳者不得食，不劳者得食;君子乘坐华丽的车子，小人的草屋不蔽风雨。', '君子得舆，民所载也;小人剥庐，终不可用也。', '君子乘坐华丽的车辆，这是老百姓沉重的负担。小人的破屋不蔽风雨，这种取象表明终究难保平安。', '', '得此爻者，须谨慎，踏实稳重者可无忧。商人生意买卖会不错。做官的会有权柄。');

// 24. 复卦 (100000)
addYao(24, 1, '初九', '吉', '不远复，无祇悔，元吉。', '出外不远就返回，没有大的过失，大吉大利。', '不远之复，以修身也。', '出外不远就返回，比喻能时时反省，严于修身。', '', '得此爻者，万事如意，经营获利。做官的会位高权重。读书人会取得佳绩。');
addYao(24, 2, '六二', '吉', '休复，吉。', '圆满而归，吉利。', '休复之吉，以下仁也。', '圆满而归之所以吉利，是能够去位让贤。', '', '得此爻者，与人共利，事业兴旺，病者痊愈。做官的遭贬者会复职。');
addYao(24, 3, '六三', '平', '频复，厉，无咎。', '愁眉苦脸地回来，是遇到了危险，知难而退可以无灾祸。', '频复之厉，义无咎也。', '虽然愁眉苦脸地回来，但已脱离危险，理应没有灾祸。', '', '得此爻者，事多反复，阴阳差错，时好时坏。做官的职位不稳定，更变无定。');
addYao(24, 4, '六四', '平', '中行独复。', '中途独自返回。', '中行独复，以从道也。', '中途独自返回，这是返回到道义上来。', '', '得此爻者，好运可期，营谋得利。做官的会复职。');
addYao(24, 5, '六五', '吉', '敦复，无悔。', '经过考察，决定返回，可以无悔。', '敦复无悔，中以自考也。', '经过考察，决定返回，可以无悔，意思是从内心用正道检察自己。', '', '得此爻者，会有积蓄，但要谨防父亲出意外。做官的有升职之机会。');
addYao(24, 6, '上六', '凶', '迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征。', '迷途难返，凶险，有灾祸。筮遇此爻，出兵打仗，终有大败，连累国君遭遇凶险，元气大伤，十年后还不能再举征伐。', '迷复之凶，反君道也。', '迷途难返遭遇凶险，这是由于君王违反君道。', '', '得此爻者，做事乖张，诸事不顺，静吉动凶。做官的会过于贪婪权力而有损。');

// 25. 无妄卦 (001001)
addYao(25, 1, '初九', '吉', '无妄，往吉。', '不要妄行非正，吉利。', '无妄之往，得志也。', '没有悖妄的行为，因为所有行动受到意志的控制。', '', '得此爻者，营谋得利。做官的会得到上司的赞许，百姓的爱戴。');
addYao(25, 2, '六二', '吉', '不耕获，不菑畲，则利有攸往。', '不耕种就想收获，不开荒地就想种熟地。这些妄谬的行径怎能有利?', '不耕获，未富也。', '不耕种而想收获，这种空妄的念头不能带来财富。', '', '得此爻者，正当好运，不劳而获。富人进财多，商人出外获利。当官的会升官。读书人会取得佳绩。');
addYao(25, 3, '六三', '凶', '无妄之灾。或系之牛，行人之得，邑人之灾。', '意外的灾难。比喻说有人将牛系在不该系的地方，行人顺手牵牛获意外之得，邑人失牛受到意外之灾。', '行人得牛，邑人灾也。', '行人意外得牛，邑人意外蒙灾。', '', '得此爻者，无妄之灾，破财损身。做官的不宜进取。');
addYao(25, 4, '九四', '平', '可贞，无咎。', '称心的占问，没有灾难。', '可贞无咎，固有之也。', '具有贞正的品德，没有灾难，理应如此。', '', '得此爻者，宜守旧，图谋有实，不致虚浮。做官的宜守职，勿妄动。');
addYao(25, 5, '九五', '平', '无妄之疾，勿药有喜。', '患意外之病，不要忙乱服药，自可痊愈。', '无妄之药，不可试也。', '出人意外的药物，不可随便服用。', '', '得此爻者，营谋有成，病得愈，或有生育之喜。做官的纵有祸难，也会不辩自明，不解自释。');
addYao(25, 6, '上九', '平', '无妄，行有眚，无攸利。', '不要胡作妄行!将有灾殃，没有好处。', '无妄之行，穷之灾也。', '谬妄的行为，是绝望无聊的表现。', '', '得此爻者，好运已过，不可妄动，否则是非迭生，唯有变通可免祸。做官的妄动有被贬职之忧。');

// 26. 大畜卦 (100111)
addYao(26, 1, '初九', '凶', '有厉，利已。', '将有危险，祭祀鬼神则能化凶为吉。', '有厉利已，不犯灾也。', '将有危险，停止所为则能化凶为吉，因为这样就不会犯灾触难。', '', '得此爻者，宜守旧，不然会有不测之祸。做官的宜退居闲职，或退位。');
addYao(26, 2, '九二', '凶', '舆说輹。', '车辐脱落，车轮坏了。', '舆说輹，中无尤也。', '车辐脱下车轮坏了，九二之爻居下卦中位，这种爻象表明毕竟没有忧患。', '', '得此爻者，谨防是非，或有足疾、腰疾。');
addYao(26, 3, '九三', '平', '良马逐，利艰贞。曰闲舆卫，利有攸往。', '良马交配。占问艰难之事吉利。每天练习防卫性车战。有所往则有利。', '利有攸往，上合志也。', '有所往则有利，所往必得，尚可符合心意。', '', '得此爻者，会得到长辈的重用，或知己相助，前运辛苦，后可有获。做官的会有实权。');
addYao(26, 4, '六四', '吉', '童牛之牿，元吉。', '将木棒横缚在好斗公牛的犄角上。筮遇此爻，大吉大利。', '六四元吉，有喜也。', '六四爻辞讲的大吉大利，是指将有喜庆之事。', '', '得此爻者，营谋有望，财富增加。做官的会有升迁之喜。');
addYao(26, 5, '六五', '吉', '豶豕之牙，吉。', '将好奔突的大猪圈起来，吉利。', '六五之吉，有庆也。', '六五爻辞讲的吉利，是指有吉庆之事。', '', '得此爻者，营谋遂意，多有喜庆之事。做官的会高升。');
addYao(26, 6, '上九', '吉', '何天之衢，亨。', '得到上天的福佑，大吉大利。', '何天之衢，道大行也。', '得到上天的福佑，行事畅通无阻。', '', '得此爻者，万事如意，心想事成，好运连连。做官的会得到上司的提拔，或被举荐而高升。读书人会进取成名。');

// 27. 颐卦 (100001)
addYao(27, 1, '初九', '凶', '舍尔灵龟，观我朵颐，凶。', '自己储藏着大量的财宝，还要羡嫉人家的财物，必遭凶险之事。', '观我朵颐，亦不足贵也。', '羡嫉人家的财物，这不是高尚的行为。', '', '得此爻者，为争夺财利而起祸，大凡心底善良守正道者可无忧。做官的会受贿，失其廉。');
addYao(27, 2, '六二', '凶', '颠颐，拂经;于丘颐，征凶。', '为了糊口，就得在山坡上开荒种地。为了生计而去抢劫别人，这是凶险之事。', '六二征凶，行失类也。', '六二爻辞说抢劫则凶，因为这种行径违反道义。', '', '得此爻者，大起大落，是非不一，凶者病致死。做官的须防被贬职。');
addYao(27, 3, '六三', '凶', '拂颐，贞凶。十年勿用，无攸利。', '违背养生正道，靠歪门邪道过活，占问得凶兆。十年都得倒霉，永无好处。', '十年勿用，道大悖也。', '十年都得倒霉，因为这种行为大有悖于道义。', '', '得此爻者，运势低迷，荒诞无稽，甚至有生死离别之伤。做官的有丧名失节之患。');
addYao(27, 4, '六四', '吉', '颠颐，吉。虎视眈眈，其欲逐逐，无咎。', '所求不过糊口，害人之心不可存，吉利。虎视眈眈，防人之心不可无。这样就可以安享天年，悠然自得，无灾祸。', '颠颐之吉，上施光也。', '《象辞》：所求不过糊口，之所以吉利，因为君上施舍甚广，足以养民。', '', '得此爻者，会得到好人的帮助，营谋遂意。做官的会得到祖上的恩惠，幸宠有加。');
addYao(27, 5, '六五', '吉', '拂经，居贞吉。不可涉大川。', '开荒种地，平居度日，占问得吉兆。筮遇此爻，不可涉水渡河。', '居贞之吉，顺以从上也。', '平居守正，之所以吉利，因为其人安份循道，服从君上。', '', '得此爻者，会有依靠，事可成，但不可乘船涉险。做官的会因人而功可成，位可保。');
addYao(27, 6, '上九', '吉', '由颐，厉吉。利涉大川。', '遵循生活正道，先艰难而终吉利。筮遇此爻，有利于涉水渡河。', '由颐厉吉，大有庆也。', '遵循生活正道，先艰难而终吉利，因为善良之人终得善报。', '', '得此爻者，营谋有成，无往不利。做官的爵禄荣重。读书人会取得佳绩。');

// 28. 大过卦 (011110)
addYao(28, 1, '初六', '平', '藉用白茅，无咎。', '恭敬地用白茅垫着祭品，可以无灾祸。', '藉用白茅，柔在下也。', '"恭敬地用白茅垫着祭品"，柔软之物铺垫在下面，正像初六阴爻居一卦之下位。', '', '得此爻者，谨慎行事，财利可固。凶者，防孝服之忧。做官的小心谨慎则禄位巩固。');
addYao(28, 2, '九二', '吉', '枯杨生稊，老夫得其女妻，无不利。', '枯杨发芽，老头子娶少女为妻，并无不吉利。', '老夫女妻，过以相与也。', '夫老妻少，年龄不当，这是错误的婚配。', '', '得此爻者，或娶妻纳妾，或生子，君子得少妻义子。做官的去位者会复职。');
addYao(28, 3, '九三', '凶', '栋桡，凶。', '屋梁弯曲，这是凶险之象。', '栋桡之凶，不可以有辅也。', '屋梁弯曲之所以凶险，因为栋曲即屋倾，无法支撑。', '', '得此爻者，须防大难而遭致家产有失，或有足目之疾。做官的须谨防被贬职。');
addYao(28, 4, '九四', '吉', '栋隆，吉。有它吝。', '屋梁挺直，吉利。但有意外之患则不好应付。', '栋隆之吉，不桡乎下也。', '屋梁挺直之所以吉利，因为屋梁不弯曲则房屋不倾倒。', '', '得此爻者，多有修造之事，可做大事，勿谋小事。做官的必能受到重用。读书人进取成名。');
addYao(28, 5, '九五', '平', '枯杨生花，老妇得其士夫，无咎无誉。', '枯杨开花，老妇人嫁给一个年轻人，这件事不好也不坏。', '枯杨生花，何可久也。老妇土夫，亦可丑也。', '枯杨开花，其花怎能长开不谢。老妇人嫁给年轻人，这种事总不大光彩。', '', '得此爻者，营谋不利，或喜中生忧，美事成丑;先逆后顺之象。做官的不可久任。');
addYao(28, 6, '上六', '凶', '过涉灭顶，凶，无咎。', '盲目涉水，水深过顶，虽遇凶险，但终归没有灾难。', '过涉之凶，不可咎也。', '盲目涉水遭致危险，事已至此，谴责亦属无益。', '', '得此爻者，不宜进取，退守为安，面部或有疾。做官的有功高震主身危之祸。');

// 29. 坎卦 (010010)
addYao(29, 1, '初六', '凶', '习坎，入于坎窞。凶。', '坎坑之中又有坎坑，陷入重坑之中，凶险。', '习坎入坎，失道凶也。', '"坎坑之中又有坎坑，陷入重坑当中"，不行坦途，偏要走险道，必招致灾殃。', '', '得此爻者，时运不佳，宜防跌入陷阱灾难之中。做官的须防小人。');
addYao(29, 2, '九二', '平', '坎有险，求小得。', '坑坑坎坎，道有险阻。敢于行险道，或小有收获。', '求小得，未出中也。', '敢于行险道，或小有收获，因为九二之爻居下卦的中位，像人尚未偏离正道。', '', '得此爻者，有小成就，女命或为侍妾，凶者防险难或生心腹血气之疾。做官的会有小的成就，大事不成。');
addYao(29, 3, '六三', '凶', '来之坎坎，险且枕，入于坎窞，勿用。', '向坑坎走来，这坑坎既险又深，陷入重坎之中，非常不利。', '来之坎坎，终无功也。', '来到这多坎之地，终无功利。', '', '得此爻者，多坎坷，多争诉之事。做官的宜退守。');
addYao(29, 4, '六四', '平', '樽酒簋贰，用缶，纳约自牖，终无咎。', '用铜樽盛酒，用圆簋盛饭。然而对于关押在坎窖里的犯人，只须用瓦盆子就行了，牢饭从天窗里送进取出，其人遭此噩运，但最后还是没有危险。', '樽酒簋贰，刚柔际也。', '"平时享受美食美器，此时用瓦盆子吃牢饭"，爻象表明六四阴爻处于九五阳爻之卞，像人被强者所压，受此磨难。', '', '得此爻者，多喜事，或有结婚之喜。做官的多饮食之乐。');
addYao(29, 5, '九五', '平', '坎不盈，祗既平，无咎。', '坎坑虽没有填满，小山头却被锄平。没有灾难。', '坎不盈，中未大也。', '小山头虽锄平，但坎坑尚未填满，说明道路不平，未成坦途。', '', '得此爻者，平淡无常，宜养精蓄锐。做官的没有危难，职位无忧。');
addYao(29, 6, '上六', '凶', '系用徵纆，寘于丛棘，三岁不得，凶。', '把犯人用绳索捆紧，投入周围有丛棘的监狱中，三年不得释放，这是凶险之事。', '上六失道，凶三岁也。', '上六爻辞所描述的，正说明官吏违背正道，违法囚人，历时三年之久。', '', '得此爻者，须防牢狱之灾。做官的须防职权旁落之忧。');

// 30. 离卦 (101101)
addYao(30, 1, '初九', '平', '履错然，敬之，无咎。', '听到纷来踏至的脚步声，立时警惕戒备，可以无灾难。', '履错之敬，以辟咎也。', '听到纷至踏来的脚步声，立时警惕戒备，可以避免灾难。', '', '得此爻者，须防无妄之灾，宜谨慎，或有足疾。做官的宜安守。');
addYao(30, 2, '六二', '吉', '黄离，元吉。', '天空出黄霓，大吉大利。', '黄离元吉，得中道也。', '黄色附丽于身，大吉大利，因为六二之爻居下卦中位，像人得中正之道。', '', '得此爻者，财利可获。做官的会受到重用。读书人会取得佳绩。');
addYao(30, 3, '九三', '凶', '日昃之离。不鼓缶而歌，则大耋之嗟，凶。', '黄昏时分有霓虹出现在天空，这是凶兆，人们居然不击鼓唱歌禳除它，老人感到悲哀，灾殃快要来了。', '日昃之离，何可久也。', '黄昏时分的霓虹，怎么会长留不散。', '', '得此爻者，乐中生悲，吉中生愁，险难迭生。做官的告休。');
addYao(30, 4, '九四', '凶', '突如其来如，焚如，死如，弃如。', '灾难突然降临，敌人见房屋就烧，见人就杀，此处变成一片废墟。', '突如其来如，无所容也。', '灾难来得如此突然，人们无处藏身逃命。', '', '得此爻者，时运不济，困难重重，或和长辈不睦，或遭官灾。');
addYao(30, 5, '六五', '平', '出涕沱若，戚嗟若，吉。', '灾难过后，人们痛哭，人们悲叹，然而吉利。', '六五之吉，离王公也。', '六五爻辞所讲的吉利，因为爻象表明，六五之爻处于上九之下，像人们能够附丽于王公而得救。', '', '得此爻者，不宜进取，宜守常。做官的在位者得志，退职者多险危。');
addYao(30, 6, '上九', '吉', '王用出征，有嘉。折首，获匪其丑，无咎。', '国王出征，反击敌人，将有嘉国的国君斩首，抓到了许多俘虏，无灾无难。', '王用出征，以正邦也。', '君王出兵反击，以安定邦国。抓到了许多俘虏，是说大获胜仗。', '', '得此爻者，时运佳，多喜事，经营获利。做官的会功成名就，读书人会取得好成绩。');

// 31. 咸卦 (011100)
addYao(31, 1, '初六', '平', '咸其拇。', '伤其大脚趾。', '咸其拇，志在外也。', '大脚趾在动，说明其志在于出行。', '', '得此爻者，行事过急，多难成就。做官的须修身养性，等待机会，京官出，闲官起。');
addYao(31, 2, '六二', '平', '咸其腓，凶，居吉。', '伤其腿肚子，这是凶兆。小腿负伤，不宜出门，安居不动，自然平安。', '虽凶居吉，顺不害也。', '虽遇凶兆，但安居不动，则可以转凶为吉。顺从贞卜之象可以避免灾害。', '', '得此爻者，奔波徒劳，宜静不宜动。做官的在位者吉，出差者有险。');
addYao(31, 3, '九三', '平', '咸其股，执其随，往吝。', '伤其股，并伤及股下之肉。带伤出行，定遭灾难。', '咸其股，亦不处也。志在随人，所执下也。', '挪动其大腿说明他不安所处。但是其志向不过是追随他人，可见他所持的主张也卑下，不足取。', '', '得此爻者，最好退守，做官的谨防被贬。');
addYao(31, 4, '九四', '平', '贞吉悔亡，憧憧往来，朋从尔思。', '贞卜吉利，无所悔恨。纷踏往来，朋友们都顺从你的意旨。', '贞吉悔亡，未感害也。憧憧往来，未光大也。', '贞正，吉利，无所悔恨，因为没有蒙受损害。虽然有几个朋友纷踏往来，但还是要耗费不少心思。', '', '得此爻者，朋友相助，可谋小事，大事有困难，心绪不定。做官的秉公执政，升迁有望。');
addYao(31, 5, '九五', '平', '咸其脢，无悔。', '伤其背肉，但没有灾祸。', '咸其脢，志末也。', '耸动其背，作出背负重物的反应，看来其志在卑微之事。', '', '得此爻者，人情不合，营谋微小。做官的多与同僚不睦。');
addYao(31, 6, '上六', '平', '咸其辅、颊、舌。', '伤其腮帮、脸颊、舌头。', '咸其辅颊舌，滕口说也。', '伤其腮帮、脸颊、舌头，这是翻腾口说招引的灾祸。', '', '得此爻者，多口舌之争，防止被他人诽谤，从事演讲、技艺、评论者吉。做官的或遭言责。');

// 32. 恒卦 (001110)
addYao(32, 1, '初六', '凶', '浚恒，贞凶，无攸利。', '掘进不止，卜问凶险，没有什么好处。', '浚恒之凶，始求深也。', '掘进不止之所以凶险，因为冒险求深，必遭崩塌之祸。', '', '得此爻者，人情乖离，前途渺茫，静守可免祸。做官的难于受到上司的赏识。');
addYao(32, 2, '九二', '平', '悔亡。', '没有悔恨。', '九二悔亡，能久中也。', '九二爻辞说没有悔恨，因为能坚守中正之道。', '', '得此爻者，安分守己则无忧。做官的宜洁身自爱，谨慎行事。');
addYao(32, 3, '九三', '凶', '不恒其德，或承之羞，贞吝。', '不能保持其德行，必然蒙受耻辱。卜问得艰难之兆。', '不恒其德，无所容也。', '不能保持其德行，反复无常，无人信任，必然落到无所容身的地步。', '', '得此爻者，须防小人诽谤，争诉之扰。做官的须防被贬。');
addYao(32, 4, '九四', '凶', '田无禽。', '畋猎无所获。', '久非其位，安得禽也?', '长久处于不适宜的环境，怎会有收获?', '', '得此爻者，营谋费力，难以成事。做官的时运不济，有所退步。');
addYao(32, 5, '六五', '凶', '恒其德，贞。妇人吉，夫子凶。', '操行一贯。卜得妇人吉利，丈夫财凶险。', '妇人贞吉，从一而终也。夫子制义，从妇凶也。', '爻辞讲妇人操守贞洁则吉利，这是符合从夫以终其身的道理。丈夫则因事制义，其道多方，如果以妇德来约束男子，则必遭凶险。', '', '得此爻者，多招毁谤，有所损失。做官的多阿谀权势而有失。');
addYao(32, 6, '上六', '凶', '振恒，凶。', '久动不息，凶险。', '振恒在上，大无功也。', '统治者朝令夕改，政令无常，其结果必所向无功。', '', '得此爻者，求名望利，小能成，大则无功，女人不利夫子。做官的会很劳累，多动少静。');

// 33. 遁卦 (001111)
addYao(33, 1, '初六', '凶', '遁尾，厉。勿用有攸往。', '君子全部隐退，国家就危险了。不能有所作为了。', '遁尾之厉，不往何灾也?', '逃遁隐藏仍未脱离危险，若能坚持苦斗，设法取胜，有什么灾难?', '', '得此爻者，宜安分守己，可无忧。做官的宜择机而退。');
addYao(33, 2, '六二', '平', '执之用黄牛之革，莫之胜说。', '抓来用黄牛革绳紧紧捆绑，这样就不能解脱了。', '执用黄牛，固志也。', '用黄牛革绳捆绑，表示意志坚固。', '', '得此爻者，家中有争执，安常守分无忧，农人有进牛畜之喜。');
addYao(33, 3, '九三', '平', '系遁，有疾厉。畜臣妾，吉。', '被拖累而不能决然隐退，就像身染重病，情形危险。在这种情况下，蓄养奴婢或可有利。', '系遁之厉，有疾惫也。畜臣妾吉，不可大事也。', '被拖累以至不能决然隐退所造成的危险，有如被疾病折腾得疲惫不堪，所以说蓄养奴婢则吉，意思是暂且养疾疗伤，不可贸然行动。', '', '得此爻者，多灾多难，良善者，得妻之力，或进人口。做官的宜急流勇退。');
addYao(33, 4, '九四', '平', '好遁，君子吉，小人否。', '喜爱隐居，这对君子是吉利的，对小人则未必。', '君子好遁，小人否也。', '君子不以利禄为心，喜爱隐居;小人以利禄为心，不甘退隐。', '', '得此爻者，虽有收获，但谨防因小人而受祸。做官的宜告休避难。');
addYao(33, 5, '九五', '吉', '嘉遁，贞吉。', '退隐以时，值得赞美，卜问前程，通泰吉利。', '嘉遁贞吉，以正志也。', '退隐以时，值得赞美;遵循正道，所以吉利，因为他存心正直，品德崇高。', '', '得此爻者，近贵多利。做官的或升迁，或功成身退。');
addYao(33, 6, '上九', '吉', '肥遁，无不利。', '远走高飞，退隐山林，无不利。', '肥遁无不利，无所疑也。', '上九爻辞讲远走高飞，退隐山林，无不利，说明其人善观形势，急流勇退。', '', '得此爻者，营谋获利，家肥业厚。做官的乐天知命，退居闲职。');

// 34. 大壮卦 (111100)
addYao(34, 1, '初九', '凶', '壮于趾，征凶，有孚。', '伤于脚趾。筮遇此爻，出征则凶，但尚有收获。', '壮于趾，其孚穷也。', '自恃兵强，侵略他国，虽有收获，但信用扫地。', '', '得此爻者，会有争诉，动则凶，须防足疾。做官的须防小人的谗言而受辱。');
addYao(34, 2, '九二', '吉', '贞吉。', '卜问得吉兆。', '九二贞吉，以中也。', '九二爻辞讲贞正吉利，因为九二之爻居下卦中位，像人守中正之道。', '', '得此爻者，营谋得意。做官的中庸处事，心中无愧。');
addYao(34, 3, '九三', '凶', '小人用壮，君子用罔;贞厉，羝羊触藩，羸其角。', '小人捕兽凭气力，君子捕兽靠网围。卜问得险兆。公羊以角撞藩，结果被篱笆卡住。', '小人用壮，君子罔也。', '小人捕兽凭气力，君子捕兽靠网围。', '', '得此爻者，或有官司之事，或家中有丧，人财不利。做官的多祸难，进退难安。');
addYao(34, 4, '九四', '吉', '贞吉，悔亡;藩决不羸，壮于大舆之輹。', '卜问得吉兆，没有悔恨。因为公羊冲决篱笆，摆脱了拘系，但又被车轮撞伤，不能乱冲乱撞了。', '藩决不羸，尚往也。', '冲决篱笆，摆脱掏系，恐其冲撞别处。', '', '得此爻者，常人得福，久静者必动，动则吉。做官的闲职者复职，进取如意。');
addYao(34, 5, '六五', '凶', '丧羊于易，无悔。', '丧羊于狄。筮遇此爻，没有大的灾祸。', '丧羊于易，位不当也。', '丧羊于狄，因为六五阴爻而居处阳位，是所处不当，像人所处环境不适当，将蒙受损失。', '', '得此爻者，一筹莫展，不能得利，病者有丧身之兆。做官的会荒于政务。');
addYao(34, 6, '上六', '平', '羝羊触藩，不能退，不能遂，无攸利。艰则吉。', '羊角插进了篱笆，退不了，进不了，处境不利。但是，目前虽处于艰难之中，最终可以化解逢吉。', '不能退，不能遂，不详也;艰则吉，咎不长也。', '不能退，不能进，陷入进退维谷之中，这是遭逢不祥。虽陷入艰难之中，最终可以化解逢吉，是说灾难不会长久。', '', '得此爻者，进退两难，多是非争诉，宜守常。做官的宜退不宜进，恐有遭贬之危。');

// 35. 晋卦 (000101)
addYao(35, 1, '初六', '平', '晋如，摧如，贞吉。罔孚，裕，无咎。', '攻击敌人，打垮敌人，卜问得吉兆。胜利之师没有捕捉俘虏，没有抢掠财物，不会有灾难。', '晋如摧如，独行正也。裕无咎，未受命也。', '攻击敌人，打垮敌人，这是因为将帅能遵循正道，所以取得了胜利。从容部署，克敌制胜，没有灾难，说明将帅能因势制宜，独断于心。', '', '得此爻者，忧愁参半，静则吉动则凶。做官的不宜进取，须防流言。');
addYao(35, 2, '六二', '吉', '晋如，愁如，贞吉。受兹介福，于其王母。', '攻击敌人，压倒敌人，卜问得吉兆。因为得到了先祖母的庇佑获得大福。', '受兹介福，以中正也。', '之所以受此大福，因为六二之爻居下卦中位，像人得中正之道。', '', '得此爻者，求谋称意，多得母亲扶助，或得妻财。做官的守正者会进取。');
addYao(35, 3, '六三', '平', '众允，悔亡。', '万众一心，全力进攻，无所悔恨。', '众允之志，上行也。', '众人信任，其志向就会实现。', '', '得此爻者，得朋友之助，营谋遂意，但谨防意外之险。做官的有升迁之机。');
addYao(35, 4, '九四', '凶', '晋如鼫鼠，贞厉。', '攻击敌人而胆小如鼠，卜问得凶兆。', '鼫鼠贞厉，位不当也。', '攻击敌人而胆小如鼠，卜问得凶兆，因为九四阳爻而居阴位，像人处于不利的地位。', '', '得此爻者，时运不佳，或有争诉。做官的不宜进取，有阻力，须守正。');
addYao(35, 5, '六五', '吉', '悔亡，失得勿恤，往吉，无不利。', '无所悔恨，吃了败仗，不要气馁。只要再接再厉，终必转败为胜。无所不利。', '失得勿恤，往有庆也。', '受到挫失，不要气馁，勇往直前，定有喜庆降临。', '', '得此爻者，好运到来，营谋获利。做官的有升迁之喜。');
addYao(35, 6, '上九', '平', '晋其角，维用伐邑，厉吉无咎，贞吝。', '攻击敌人，必须较量敌我双方的力量，可以考虑攻击敌人的城邑。但其结局难料：或许危险，或许吉利，或许没有灾难，或许正践凶兆。', '维用伐邑，道未光也。', '考虑到攻击敌人的城邑，这说明王道未能广泛实行，以致属邑叛乱。', '', '得此爻者，有修屋宇之喜，不良者有争诉之忧。做官的有食邑之荣。');

// 36. 明夷卦 (101000)
addYao(36, 1, '初九', '平', '明夷于飞，垂其翼。君子于行，三日不食。有攸往，主人有言。', '"鹈鹕在飞翔，停栖在沼畔。君子离家走，三日无食粮。"筮遇此爻，有所往，则必遭主人谴责。', '君子于行，义不食也。', '君子在旅途中，依礼义不能蒙羞受食。', '', '得此爻者，或有手足之伤，善者有进财纳福之喜。做官的有飞黄腾达之象，但谨防有失。');
addYao(36, 2, '六二', '吉', '明夷，夷于左股，用拯马壮，吉。', '鹈鹕，鹈鹕，伤于左股，君子负伤，因马获救。吉利。', '六二之吉，顺以则也。', '六二爻辞所讲的吉利，是因为六二阴爻处于九三阳爻之下，正像马顺从主人善体人意。', '', '得此爻者，常人或有难，但会得贵人之助。做官的会有实权，能当大任。读书人会取得好成绩。');
addYao(36, 3, '九三', '平', '明夷于南狩，得其大首，不可疾，贞。', '在南方的猎区，拉弓射箭，获得一些大野兽。筮遇此爻，占问疾病则不利。', '南狩之志，乃大得也。', '决心在南方狩猎，大称其意。', '', '得此爻者，有修屋宇造作之兆。不良者，左股或有伤，多忧愁分离之患。');
addYao(36, 4, '六四', '平', '入于左腹，获明夷之心，于出门庭。', '回到深隐之处吧!走出居室，进入社会，就感到环境的险恶，退隐的念头油然而生。', '入于左腹，获心意也。', '回到深隐之处，就满足了退隐的心意。', '', '得此爻者，出外营谋者会顺利，妇人有孕者生男，不良者或生心腹之疾。做官的闲职者会复职，在职者，多出外任职，韬光养晦者必出身成名。');
addYao(36, 5, '六五', '平', '箕子之明夷，利贞。', '殷亡后，箕子逃到东方邻国避难，卜问得吉兆。', '箕子之贞，明不可息也。', '箕子退隐守正，他的光辉形象千古不灭。', '', '得此爻者，难逢知己，或有家难之祸。做官的须修德养性可保无忧。');
addYao(36, 6, '上六', '凶', '不明，晦。初登于天，后入于地。', '阳光消失了，天黑了。太阳初升，君子进仕之象;太阳隐没，君子退隐之象。', '初登于天，照四国也;后入于地，失则也。', '太阳初升，君子进仕，光照四方。太阳隐没，君子引退，国无楷模。', '', '得此爻者，先喜后忧，老者或不寿。做官的防止遭人流言，或被贬。');

// 37. 家人卦 (110101)
addYao(37, 1, '初九', '平', '闲有家，悔亡。', '治家严谨，没有悔恨。', '闲有家，志未变也。', '治家严谨，没有悔恨，因为志向没有改变。', '', '得此爻者，家庭和睦，万事顺遂。做官的会严于律己，家人和睦。');
addYao(37, 2, '六二', '吉', '无攸遂，在中馈，贞吉。', '没有什么成就，在家中做饭，贞卜吉利。', '六二之吉，顺以巽也。', '六二爻辞讲的吉利，是因为顺从谦逊。', '', '得此爻者，家庭和睦，妇女持家有方。做官的会家庭美满，事业顺利。');
addYao(37, 3, '九三', '平', '家人嗃嗃，悔厉吉。妇子嘻嘻，终吝。', '家人之间互相责备，虽然有悔恨和危险，但最终吉利。妇人和孩子嘻嘻哈哈，最终会有困难。', '家人嗃嗃，未失也;妇子嘻嘻，失家节也。', '家人之间互相责备，没有失去什么;妇人和孩子嘻嘻哈哈，失去了家庭的礼节。', '', '得此爻者，家庭严肃则吉，过于放纵则凶。做官的须严以律己，宽以待人。');
addYao(37, 4, '六四', '平', '富家，大吉。', '使家庭富裕，大吉大利。', '富家大吉，顺在位也。', '使家庭富裕，大吉大利，因为顺从在位者。', '', '得此爻者，家庭富裕，万事如意。做官的会家庭美满，事业顺利。');
addYao(37, 5, '九五', '吉', '王假有家，勿恤吉。', '君王到宗庙举行祭祀。占得此卦，不用担忧。', '王假有家，交相爱也。', '君王到宗庙举行祭祀，说明君臣之间互相爱护。', '', '得此爻者，家庭和睦，万事如意。做官的会得到君王的赏识，事业顺利。');
addYao(37, 6, '上九', '平', '有孚威如，终吉。', '有诚信而有威严，最终吉利。', '威如之吉，反身之谓也。', '有诚信而有威严，最终吉利，是说要反过来要求自己。', '', '得此爻者，有诚信而有威严，万事顺遂。做官的会以身作则，得到下属的尊重。');

// 38. 睽卦 (101011)
addYao(38, 1, '初九', '平', '悔亡，丧马勿逐，自复。见恶人，无咎。', '不必悔恨，丢失了马匹，不必寻找，它自会回来，途中碰见坏人，也不会有灾祸。', '见恶人，以辟咎也。', '遇见坏人之所以无灾祸，意在消除恶人的恶意。', '', '得此爻者，营谋先失而后得，人事先离而后合，谨防凶恶之灾患。做官的闲职者复职，被贬者复升。');
addYao(38, 2, '九二', '平', '遇主于巷，无咎。', '遇着了热情好客的主人，没有灾难。', '遇主于巷，未失道也。', '遇着了热情好客的主人，这说明没有迷失道路。', '', '得此爻者，会得知己，营谋遂意。做官的会遇到明主，升迁有望。');
addYao(38, 3, '六三', '凶', '见舆曳，其牛掣。其人天且劓，无初有终。', '看见一辆拉货的车，拉车的牛一俯一仰拉得很费劲，赶车的人是—个烙了额，割了鼻的奴隶。起初车子陷着不动，后来终于拉动了。', '见舆曳，位不当也;无初有终，遇刚也。', '看见一个烙额割鼻的奴隶在拉车，爻象表明：六三阴爻而居于阳位，所处不当，像人落入了悲苦的境地。起初不顺，结局倒好，因为六三阴爻上进遇到九四阳爻，像人得到强者的帮助。', '', '得此爻者，谋望有阻，险中求安，先迷后顺。不良者有骨肉刑伤之厄。做官的须防小人的谗言。');
addYao(38, 4, '九四', '平', '睽孤，遇元夫。交孚，厉无咎。', '旅人孤单地行路，遇上一个跛子，一同被抓住，情形危险，但终无灾祸。', '交孚无咎，志行也。', '交相信任，必无灾难，说明其志得行，目的达到。', '', '得此爻者，能得到朋友的帮助，转危为安，求婚者必配。做官的会得到同僚的推荐，升迁有机。');
addYao(38, 5, '六五', '平', '悔亡，厥宗噬肤，往何咎?', '没有悔恨。瞧见同族宗人在吃肉，孤单的旅人欣然结伴同行，一路平安无事。', '厥宗噬肤，往有庆也。', '同族宗人在吃肉，前往，必有喜庆之事。', '', '得此爻者，经营获利，抬举有人。不良者，亲朋怨恶，骨肉刑伤，官司牵连。做官的会获得成就与名望，读书人会取得佳绩。');
addYao(38, 6, '上九', '平', '睽孤，见豕负涂，载鬼一车。先张之弧，后说之弧，匪寇婚媾。往遇雨则吉。', '旅人孤单地行路，见一头大猪伏在路上，又遇上一辆大车，上面满载着打扮得奇形怪状的人。旅人搭弓欲射，后来又放下弓箭。因为这伙人不是强盗，而是去订婚的。旅人照常行进，遇上大雨，但一切平安。', '遇雨之吉，群疑亡也。', '上九爻辞讲的旅人途遇婚媾之人，开始相互猜疑，几致动武，后来相安无事，照常旅行。这是因为双方疑惧消失了。', '', '得此爻者，遭污受诬，先损后益。做官的须防被诽谤之忧。');

// 39. 蹇卦 (010100)
addYao(39, 1, '初六', '平', '往蹇来誉。', '出门艰难，归来安适。', '往蹇来誉，宜待也。', '出门艰难，归来安适，知难而退，坐待时机。', '', '得此爻者，宜守旧安常。做官的稳步进取，好运将至。');
addYao(39, 2, '六二', '凶', '王臣蹇蹇，匪躬之故。', '王臣之所以屡犯艰难，并不是为自身私利。', '王臣蹇蹇，终无尤也。', '王臣出以公心屡犯艰难，其自身始终没有过失。', '', '得此爻者，涉艰历险，营谋有阻。做官的宜保持忠贞，报效国家。');
addYao(39, 3, '九三', '平', '往蹇来反。', '出门困难重重，归来笑逐颜开。', '往蹇来反，内喜之也。', '出门困难重重，归来笑逐颜开，这是发自内心的喜悦。', '', '得此爻者，不宜进取，或有妻子之喜。做官的位高者会晋升。');
addYao(39, 4, '六四', '凶', '往蹇来连。', '出门步履艰难，归来时却有车可乘。', '往蹇来连，当位实也。', '出门步履艰难，归来时却有车可乘，因为六四阴爻居阴位，像人才正当其位，德符其名。', '', '得此爻者，不良者会有争诉。做官的进升有机，求名望利皆有实而不虚。');
addYao(39, 5, '九五', '吉', '大蹇，朋来。', '经历了很多艰难困苦，终予获得大利。', '大蹇朋来，以中节也。', '大难当前，得到友人相助，因为九五之爻居上卦中位，像人节操贞正自能获救。', '', '得此爻者，会得到贵人提举，无往不利。');
addYao(39, 6, '上六', '吉', '往蹇来硕，吉。利见大人。', '出门困难重重，归来欢喜跳跃。筮遇此爻，吉利，利于会见贵族王公。', '往蹇来硕，志在内也;利见大人，以从贵也。', '出门困难重重，归来欢喜跳跃，说明志气高昂，奋勇取胜。爻辞说：利于会见贵族王公，说明追随贵人，必获福利。', '', '得此爻者，好运来到，营谋遂意。做官的会身居要职，读书人进取成名。');

// 40. 解卦 (001010)
addYao(40, 1, '初六', '平', '无咎。', '筮遇此爻，没有灾难。', '刚柔之际，义无咎也。', '初六与九二相接，为刚柔相应之象，喻君臣、夫妻和衷共济，其义自无灾难。', '', '得此爻者，经营者吉，未婚者配。做官的德位相称，晋升有望，读书人会取得好成绩。');
addYao(40, 2, '九二', '吉', '田获三狐，得黄矢，贞吉。', '畋猎获得三只狐狸，猎物身上带着铜箭头。卜问得吉兆。', '九二贞吉，得中道也。', '九二爻辞讲的卜问得吉兆，因为九二之爻居下卦中位，像其人行事遵循正道。', '', '得此爻者，正当好运，财利可获。做官的会荣华富贵，读书人会取得佳绩。');
addYao(40, 3, '六三', '凶', '负且乘，致寇至，贞吝。', '带着许多财物，又是背负，又是车拉，招摇惹盗，自然招致盗寇抢劫，卜问有灾祸之象。', '负且乘，亦可丑也;自我致戎，又谁咎也。', '带着许多财物，又是背负，又是车拉，招摇惹盗，这是愚蠢可耻之事，由于自已慢藏诲盗，招致盗寇，又能谴责谁呢?', '', '得此爻者，须防窃盗，是非诉讼。做官的谨防被贬之忧。');
addYao(40, 4, '九四', '凶', '解而拇，朋至斯孚。', '赚了钱，而懒怠不想走，结果被人虏去。', '解而拇，未当位也。', '懒怠不想动，说明其人怠于职守，不称其位。', '', '得此爻者，须防小人，或交友不慎之祸。');
addYao(40, 5, '六五', '吉', '君子维有解，吉，有孚于小人。', '君子被拘囚后又获释，吉利;小人则将受罚。', '君子有解，小人退也。', '君子解除了小人的职务，说明小人被摒退。', '', '得此爻者，正当好运，君子有利，病者愈。做官的会身居要职。');
addYao(40, 6, '上六', '吉', '公用射隼于高墉之上，获之无不利。', '在高高的城墙上，王公射中一只鹰，并且抓到了，这没有什么不吉利的。', '公用射隼，以解悖也。', '王公射鹰，意在除强去暴。', '', '得此爻者，运途顺利，多营谋获利。做官的闲职者会复职，居要位。');

// 41. 损卦 (110001)
addYao(41, 1, '初九', '吉', '已事遄往，无咎，酌损之。', '祭祀完毕，立即前往，没有灾祸，酌量减损。', '已事遄往，尚合志也。', '祭祀完毕立即前往，说明志在合作。', '', '得此爻者，营谋得利，宜速不宜迟。做官的会得到上司的重用。');
addYao(41, 2, '九二', '吉', '利贞，征凶。弗损益之。', '吉利的贞卜，出征凶险。不要减损，要增益。', '九二利贞，中以为志也。', '九二爻辞讲吉利的贞卜，因为居位中正。', '', '得此爻者，宜守正，不宜进取。做官的会得到升迁。');
addYao(41, 3, '六三', '平', '三人行则损一人，一人行则得其友。', '三人同行会损一人，一人独行会得到朋友。', '一人行，三则疑也。', '一人独行得到朋友，说明三人同行会产生猜疑。', '', '得此爻者，宜独行，不宜多人同行。做官的须防小人离间。');
addYao(41, 4, '六四', '平', '损其疾，使遄有喜，无咎。', '减损疾病，迅速治愈，没有灾祸。', '损其疾，亦可喜也。', '减损疾病，这也是可喜的事。', '', '得此爻者，疾病会痊愈，有喜庆之事。做官的会消除弊病。');
addYao(41, 5, '六五', '吉', '或益之，十朋之龟弗克违，元吉。', '有人赠送价值十朋的大龟，不可违背，大吉大利。', '六五元吉，自上祐也。', '六五爻辞讲大吉大利，因为得到上天的保佑。', '', '得此爻者，会得到贵人的帮助，万事如意。做官的会得到君王的赏赐。');
addYao(41, 6, '上九', '吉', '弗损益之，无咎，贞吉，利有攸往。得臣无家。', '不减损反而增益，没有灾祸，贞卜吉利，有利于有所往。得到臣民但没有家室。', '弗损益之，大得志也。', '不减损反而增益，说明志向得以实现。', '', '得此爻者，万事如意，大吉大利。做官的会得到臣民的拥护。');

// 42. 益卦 (100011)
addYao(42, 1, '初九', '吉', '利用为大作，元吉，无咎。', '利于做大事，大吉大利，没有灾祸。', '元吉无咎，下不厚事也。', '大吉大利没有灾祸，说明在下位的人不会做过分的事。', '', '得此爻者，会有大的成就，万事如意。做官的会得到重用。');
addYao(42, 2, '六二', '吉', '或益之，十朋之龟弗克违，永贞吉。王用享于帝，吉。', '有人赠送价值十朋的大龟，不可违背，永久贞卜吉利。君王祭祀上帝，吉利。', '或益之，自外来也。', '有人赠送，说明来自外部。', '', '得此爻者，会得到贵人的帮助，万事如意。做官的会得到君王的赏赐。');
addYao(42, 3, '六三', '平', '益之用凶事，无咎。有孚中行，告公用圭。', '用增益来处理凶事，没有灾祸。心怀诚信行中正之道，用圭玉告诉王公。', '益用凶事，固有之也。', '用增益来处理凶事，说明本来就有这种准备。', '', '得此爻者，会得到朋友的帮助，化凶为吉。做官的会得到同僚的支持。');
addYao(42, 4, '六四', '平', '中行，告公从。利用为依迁国。', '行中正之道，告诉王公听从。利于依靠迁移国家。', '告公从，以益志也。', '告诉王公听从，说明志在增益。', '', '得此爻者，会得到王公的支持，万事如意。做官的会得到君王的信任。');
addYao(42, 5, '九五', '吉', '有孚惠心，勿问元吉。有孚惠我德。', '心怀诚信仁爱之心，不用问就知道大吉大利。别人也会以诚信仁爱之心对待我。', '有孚惠心，勿问之矣。惠我德，大得志也。', '心怀诚信仁爱之心，不用问就知道。别人也会以诚信仁爱之心对待我，说明志向得以实现。', '', '得此爻者，心怀诚信，万事如意。做官的会得到百姓的爱戴。');
addYao(42, 6, '上九', '平', '莫益之，或击之，立心勿恒，凶。', '没有人增益，反而有人攻击，树立的心志不持久，凶险。', '莫益之，偏辞也。或击之，自外来也。', '没有人增益，说明言辞偏颇。有人攻击，说明来自外部。', '', '得此爻者，须防小人攻击，宜坚守正道。做官的须防小人陷害。');

// 43. 夬卦 (011111)
addYao(43, 1, '初九', '平', '壮于前趾，往不胜为咎。', '脚趾强壮，前往不能取胜会有灾祸。', '不胜而往，咎也。', '不能取胜而前往，会有灾祸。', '', '得此爻者，宜守不宜进，否则会有灾祸。做官的须防冒进失利。');
addYao(43, 2, '九二', '吉', '惕号，莫夜有戎，勿恤。', '警惕呼号，夜里有战事，不要忧虑。', '有戎勿恤，得中道也。', '夜里有战事不要忧虑，因为居位中正。', '', '得此爻者，会有战事，但最终会化险为夷。做官的须防战事。');
addYao(43, 3, '九三', '平', '壮于頄，有凶。君子夬夬，独行遇雨，若濡有愠，无咎。', '颧骨强壮，有凶险。君子果断行事，独自前行遇到下雨，好像被淋湿有些烦恼，但没有灾祸。', '君子夬夬，终无咎也。', '君子果断行事，最终没有灾祸。', '', '得此爻者，须防凶险，但最终会化险为夷。做官的须防凶险。');
addYao(43, 4, '九四', '平', '臀无肤，其行次且。牵羊悔亡，闻言不信。', '臀部没有皮肤，行走困难。牵着羊没有悔恨，但听到的话不可信。', '闻言不信，聪不明也。', '听到的话不可信，说明听觉不明。', '', '得此爻者，须防行走困难，听到的话不可信。做官的须防小人的谗言。');
addYao(43, 5, '九五', '吉', '苋陆夬夬，中行无咎。', '果断地铲除苋陆，行中正之道没有灾祸。', '中行无咎，中未光也。', '行中正之道没有灾祸，但尚未发扬光大。', '', '得此爻者，会果断行事，没有灾祸。做官的会清除小人。');
addYao(43, 6, '上六', '平', '无号，终有凶。', '没有呼号，最终有凶险。', '无号之凶，终不可长也。', '没有呼号的凶险，最终不会长久。', '', '得此爻者，须防凶险，宜呼号求救。做官的须防凶险。');

// 44. 姤卦 (111110)
addYao(44, 1, '初六', '平', '系于金柅，贞吉。有攸往，见凶，羸豕孚蹢躅。', '系在金车上，贞卜吉利。有所往，见凶险，瘦弱的猪在徘徊。', '系于金柅，柔道牵也。', '系在金车上，说明柔弱之道被牵制。', '', '得此爻者，宜守不宜进，否则会有凶险。做官的须防小人。');
addYao(44, 2, '九二', '吉', '包有鱼，无咎，不利宾。', '厨房里有鱼，没有灾祸，但不利于宾客。', '包有鱼，义不及宾也。', '厨房里有鱼，从道义上说不给宾客。', '', '得此爻者，会有收获，但不利于宾客。做官的会得到好处。');
addYao(44, 3, '九三', '平', '臀无肤，其行次且，厉，无大咎。', '臀部没有皮肤，行走困难，有危险，但没有大的灾祸。', '其行次且，行未牵也。', '行走困难，说明行动没有被牵制。', '', '得此爻者，会有困难，但没有大的灾祸。做官的须防困难。');
addYao(44, 4, '九四', '平', '包无鱼，起凶。', '厨房里没有鱼，出现凶险。', '无鱼之凶，远民也。', '没有鱼的凶险，说明远离民众。', '', '得此爻者，会有凶险，宜警惕。做官的须防失民心。');
addYao(44, 5, '九五', '吉', '以杞包瓜，含章，有陨自天。', '用杞树枝包裹瓜，蕴含文采，有东西从天上坠落。', '九五含章，中正也。有陨自天，志不舍命也。', '九五爻辞讲蕴含文采，因为居位中正。有东西从天上坠落，说明志向不舍弃天命。', '', '得此爻者，会有意外之喜，万事如意。做官的会得到上天的保佑。');
addYao(44, 6, '上九', '平', '姤其角，吝，无咎。', '相遇在角落，有困难，但没有灾祸。', '姤其角，上穷吝也。', '相遇在角落，说明在上位穷困。', '', '得此爻者，会有困难，但没有灾祸。做官的须防穷困。');

// 45. 萃卦 (011000)
addYao(45, 1, '初六', '平', '有孚不终，乃乱乃萃，若号一握为笑，勿恤，往无咎。', '有诚信但不持久，于是混乱聚集，如果呼号握手言笑，不要忧虑，前往没有灾祸。', '乃乱乃萃，其志乱也。', '于是混乱聚集，说明心志混乱。', '', '得此爻者，会有混乱，但最终会和好。做官的须防混乱。');
addYao(45, 2, '六二', '吉', '引吉，无咎，孚乃利用禴。', '引导吉利，没有灾祸，心怀诚信利于祭祀。', '引吉无咎，中未变也。', '引导吉利没有灾祸，说明居中不变。', '', '得此爻者，会得到引导，万事如意。做官的会得到上司的引导。');
addYao(45, 3, '六三', '凶', '萃如嗟如，无攸利，往无咎，小吝。', '聚集叹息，没有好处，前往没有灾祸，但有小的困难。', '往无咎，上巽也。', '前往没有灾祸，因为对上谦逊。', '', '得此爻者，会有叹息，但前往没有灾祸。做官的须防叹息。');
addYao(45, 4, '九四', '平', '大吉，无咎。', '大吉大利，没有灾祸。', '大吉无咎，位不当也。', '大吉大利没有灾祸，但位置不当。', '', '得此爻者，万事如意，大吉大利。做官的会得到好处。');
addYao(45, 5, '九五', '吉', '萃有位，无咎。匪孚，元永贞，悔亡。', '聚集在高位，没有灾祸。不被信任，永久贞卜吉利，悔恨消失。', '萃有位，志未光也。', '聚集在高位，说明志向尚未发扬光大。', '', '得此爻者，会聚集在高位，万事如意。做官的会身居高位。');
addYao(45, 6, '上六', '平', '赍咨涕洟，无咎。', '悲伤流泪，没有灾祸。', '赍咨涕洟，未安上也。', '悲伤流泪，说明在上位不安。', '', '得此爻者，会有悲伤，但没有灾祸。做官的须防悲伤。');

// 46. 升卦 (000110)
addYao(46, 1, '初六', '吉', '允升，大吉。', '适宜上升，大吉大利。', '允升大吉，上合志也。', '适宜上升大吉大利，说明与上面的人志向相合。', '', '得此爻者，会上升，万事如意。做官的会得到升迁。');
addYao(46, 2, '九二', '吉', '孚乃利用禴，无咎。', '心怀诚信利于祭祀，没有灾祸。', '九二之孚，有喜也。', '九二爻辞讲心怀诚信，说明有喜庆之事。', '', '得此爻者，会有喜庆之事，万事如意。做官的会得到君王的信任。');
addYao(46, 3, '九三', '平', '升虚邑。', '上升到空虚的城邑。', '升虚邑，无所疑也。', '上升到空虚的城邑，说明没有疑虑。', '', '得此爻者，会上升到空虚的城邑，万事如意。做官的会得到升迁。');
addYao(46, 4, '六四', '平', '王用亨于岐山，吉，无咎。', '君王在岐山祭祀，吉利，没有灾祸。', '王用亨于岐山，顺事也。', '君王在岐山祭祀，说明顺从其事。', '', '得此爻者，会有祭祀之事，万事如意。做官的会得到君王的重用。');
addYao(46, 5, '六五', '吉', '贞吉，升阶。', '贞卜吉利，登上台阶。', '贞吉升阶，大得志也。', '贞卜吉利登上台阶，说明志向得以实现。', '', '得此爻者，会登上台阶，万事如意。做官的会得到升迁。');
addYao(46, 6, '上六', '平', '冥升，利于不息之贞。', '在黑暗中上升，利于不停息的贞卜。', '冥升在上，消不富也。', '在黑暗中上升在上位，说明消耗不富裕。', '', '得此爻者，会在黑暗中上升，须不停息。做官的须防黑暗。');

// 47. 困卦 (010110)
addYao(47, 1, '初六', '平', '臀困于株木，入于幽谷，三岁不觌。', '臀部困在树干上，进入幽深的山谷，三年不见人。', '入于幽谷，幽不明也。', '进入幽深的山谷，说明幽暗不明。', '', '得此爻者，会陷入困境，须等待时机。做官的须防困境。');
addYao(47, 2, '九二', '吉', '困于酒食，朱绂方来，利用享祀。征凶，无咎。', '困在酒食中，红色的官服刚刚到来，利于祭祀。出征凶险，没有灾祸。', '困于酒食，中有庆也。', '困在酒食中，说明居中会有喜庆。', '', '得此爻者，会有酒食之困，但最终会有喜庆。做官的会得到官服。');
addYao(47, 3, '六三', '凶', '困于石，据于蒺藜，入于其宫，不见其妻，凶。', '困在石头上，依靠蒺藜，进入他的宫室，见不到他的妻子，凶险。', '据于蒺藜，乘刚也。入于其宫不见其妻，不祥也。', '依靠蒺藜，说明乘凌于刚爻之上。进入他的宫室见不到他的妻子，说明不祥。', '', '得此爻者，会有凶险，须防不测。做官的须防凶险。');
addYao(47, 4, '九四', '平', '来徐徐，困于金车，吝，有终。', '缓慢前来，困在金车上，有困难，但有好的结局。', '来徐徐，志在下也。虽不当位，有与也。', '缓慢前来，说明志向在于下面。虽然位置不当，但有帮助。', '', '得此爻者，会有困难，但最终会有好的结局。做官的须防困难。');
addYao(47, 5, '九五', '吉', '劓刖，困于赤绂，乃徐有说，利用祭祀。', '被割鼻断足，困在红色的官服中，慢慢会有喜悦，利于祭祀。', '劓刖，志未得也。乃徐有说，以中直也。', '被割鼻断足，说明志向没有得到。慢慢会有喜悦，因为居中正直。', '', '得此爻者，会有困境，但慢慢会有喜悦。做官的须防困境。');
addYao(47, 6, '上六', '平', '困于葛藟，于臲卼，曰动悔有悔，征吉。', '困在葛藤中，不安稳，说行动悔恨又悔恨，出征吉利。', '困于葛藟，未当也。动悔有悔，吉行也。', '困在葛藤中，说明位置不当。行动悔恨又悔恨，说明吉利的行动。', '', '得此爻者，会有困境，但出征吉利。做官的须防困境。');

// 48. 井卦 (011010)
addYao(48, 1, '初六', '平', '井泥不食，旧井无禽。', '井里有泥不能饮用，旧井没有禽鸟。', '井泥不食，下也。旧井无禽，时舍也。', '井里有泥不能饮用，说明在下位。旧井没有禽鸟，说明被舍弃。', '', '得此爻者，会被舍弃，须防困境。做官的须防被舍弃。');
addYao(48, 2, '九二', '吉', '井谷射鲋，瓮敝漏。', '在井底射小鱼，瓮破漏水。', '井谷射鲋，无与也。', '在井底射小鱼，说明没有帮助。', '', '得此爻者，会有破漏，须防损失。做官的须防破漏。');
addYao(48, 3, '九三', '平', '井渫不食，为我心恻，可用汲，王明，并受其福。', '井淘干净了但没人饮用，让我心里悲伤，可以汲取，君王圣明，大家都受其福。', '井渫不食，行恻也。求王明，受福也。', '井淘干净了但没人饮用，说明行为让人悲伤。寻求君王圣明，说明接受福气。', '', '得此爻者，会有悲伤，但最终会有福气。做官的须防不被重用。');
addYao(48, 4, '六四', '平', '井甃，无咎。', '井壁砌好了，没有灾祸。', '井甃无咎，修井也。', '井壁砌好了没有灾祸，说明修井。', '', '得此爻者，会修好井，没有灾祸。做官的会修好事情。');
addYao(48, 5, '九五', '吉', '井冽，寒泉食。', '井水清澈，寒泉可以饮用。', '寒泉之食，中正也。', '寒泉可以饮用，因为居位中正。', '', '得此爻者，会有清澈的井水，万事如意。做官的会得到君王的信任。');
addYao(48, 6, '上六', '平', '井收勿幕，有孚元吉。', '井收好了不要盖上，有诚信大吉大利。', '元吉在上，大成也。', '大吉大利在上位，说明大功告成。', '', '得此爻者，会有大功告成，万事如意。做官的会得到成功。');

// 49. 革卦 (011101)
addYao(49, 1, '初九', '平', '巩用黄牛之革。', '用黄牛的皮革加固。', '巩用黄牛，不可以有为也。', '用黄牛的皮革加固，说明不可以有所作为。', '', '得此爻者，宜巩固，不宜有所作为。做官的须防有所作为。');
addYao(49, 2, '六二', '吉', '巳日乃革之，征吉，无咎。', '到了巳日才改革，出征吉利，没有灾祸。', '巳日革之，行有嘉也。', '到了巳日才改革，说明行动会有嘉奖。', '', '得此爻者，会有改革，出征吉利。做官的会得到嘉奖。');
addYao(49, 3, '九三', '平', '征凶，贞厉。革言三就，有孚。', '出征凶险，贞卜危险。改革的言论三次成功，有诚信。', '革言三就，又何之矣。', '改革的言论三次成功，又能到哪里去呢。', '', '得此爻者，会有改革，但须防凶险。做官的须防凶险。');
addYao(49, 4, '九四', '平', '悔亡，有孚改命，吉。', '悔恨消失，有诚信改变命令，吉利。', '改命之吉，信志也。', '改变命令的吉利，说明诚信志向。', '', '得此爻者，会改变命令，吉利。做官的会改变命令。');
addYao(49, 5, '六五', '吉', '大人虎变，未占有孚。', '大人像老虎一样变化，没有占问就有诚信。', '大人虎变，其文炳也。', '大人像老虎一样变化，说明文采炳焕。', '', '得此爻者，会有大的变化，万事如意。做官的会有大的变化。');
addYao(49, 6, '上六', '平', '君子豹变，小人革面，征凶，居贞吉。', '君子像豹子一样变化，小人改变面目，出征凶险，居守贞卜吉利。', '君子豹变，其文蔚也。小人革面，顺以从君也。', '君子像豹子一样变化，说明文采蔚然。小人改变面目，说明顺从君王。', '', '得此爻者，会有变化，须防出征凶险。做官的须防出征凶险。');

// 50. 鼎卦 (101110)
addYao(50, 1, '初六', '平', '鼎颠趾，利出否。得妾以其子，无咎。', '鼎颠倒了脚，利于倒出脏东西。得到妾和她的儿子，没有灾祸。', '鼎颠趾，未悖也。利出否，以从贵也。', '鼎颠倒了脚，说明没有违背。利于倒出脏东西，说明顺从贵人。', '', '得此爻者，会有颠倒，但利于倒出脏东西。做官的须防颠倒。');
addYao(50, 2, '九二', '吉', '鼎有实，我仇有疾，不我能即，吉。', '鼎里有食物，我的仇人有疾病，不能接近我，吉利。', '鼎有实，慎所之也。我仇有疾，终无尤也。', '鼎里有食物，说明谨慎前往。我的仇人有疾病，说明最终没有灾祸。', '', '得此爻者，会有食物，仇人有疾病，吉利。做官的会得到好处。');
addYao(50, 3, '九三', '平', '鼎耳革，其行塞，雉膏不食。方雨亏悔，终吉。', '鼎耳变了，行走阻塞，野鸡膏不能食用。正当下雨亏损悔恨，最终吉利。', '鼎耳革，失其义也。', '鼎耳变了，说明失去了意义。', '', '得此爻者，会有阻塞，但最终吉利。做官的须防阻塞。');
addYao(50, 4, '九四', '平', '鼎折足，覆公餗，其形渥，凶。', '鼎折断了脚，倾覆了王公的美食，其形状龌龊，凶险。', '覆公餗，信如何也。', '倾覆了王公的美食，说明信用如何呢。', '', '得此爻者，会有凶险，须防倾覆。做官的须防凶险。');
addYao(50, 5, '六五', '吉', '鼎黄耳金铉，利贞。', '鼎有黄色的耳朵和金色的铉，利于贞卜。', '鼎黄耳，中以为实也。', '鼎有黄色的耳朵，说明居中以为实。', '', '得此爻者，会有黄色的耳朵和金色的铉，利于贞卜。做官的会得到好处。');
addYao(50, 6, '上九', '平', '鼎玉铉，大吉，无不利。', '鼎有玉铉，大吉大利，无所不利。', '玉铉在上，刚柔节也。', '玉铉在上位，说明刚柔相节。', '', '得此爻者，会有玉铉，大吉大利。做官的会得到大吉大利。');

// 51. 震卦 (111001)
addYao(51, 1, '初九', '平', '震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。', '雷声传来，人们恐惧颤抖，随后又谈笑自若。雷声震惊百里，却没有丢失祭祀用的酒器。', '震来虩虩，恐致福也。笑言哑哑，后有则也。', '雷声传来人们恐惧颤抖，说明恐惧会带来福气。随后又谈笑自若，说明后来有法则。', '', '得此爻者，会有恐惧，但最终会谈笑自若。做官的须防恐惧。');
addYao(51, 2, '六二', '吉', '震来厉，亿丧贝。跻于九陵，勿逐，七日得。', '雷声传来有危险，丧失了大量的财物。登上九重山陵，不要追逐，七天会得到。', '震来厉，乘刚也。', '雷声传来有危险，说明乘凌于刚爻之上。', '', '得此爻者，会有危险，但最终会得到。做官的须防危险。');
addYao(51, 3, '六三', '平', '震苏苏，震行无眚。', '雷声让人苏醒，雷声行走没有灾祸。', '震苏苏，位不当也。', '雷声让人苏醒，说明位置不当。', '', '得此爻者，会苏醒，没有灾祸。做官的须防位置不当。');
addYao(51, 4, '九四', '平', '震遂泥。', '雷声陷入泥中。', '震遂泥，未光也。', '雷声陷入泥中，说明尚未发扬光大。', '', '得此爻者，会陷入泥中，须防困境。做官的须防困境。');
addYao(51, 5, '六五', '吉', '震往来厉，亿无丧，有事。', '雷声往来有危险，没有丧失大量财物，有事情。', '震往来厉，危行也。其事在中，大无丧也。', '雷声往来有危险，说明危险的行动。其事在中间，说明没有大的丧失。', '', '得此爻者，会有危险，但没有大的丧失。做官的须防危险。');
addYao(51, 6, '上六', '平', '震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。', '雷声让人恐惧，目光惊恐，出征凶险。雷声不在自己身上，而在邻居身上，没有灾祸。婚姻有言语之争。', '震索索，中未得也。虽凶无咎，畏邻戒也。', '雷声让人恐惧，说明中间没有得到。虽然凶险没有灾祸，说明畏惧邻居的警戒。', '', '得此爻者，会有恐惧，但没有灾祸。做官的须防恐惧。');

// 52. 艮卦 (100100)
addYao(52, 1, '初六', '平', '艮其趾，无咎，利永贞。', '止住脚趾，没有灾祸，利于永久贞卜。', '艮其趾，未失正也。', '止住脚趾，说明没有失去正道。', '', '得此爻者，宜止住，没有灾祸。做官的须防前行。');
addYao(52, 2, '六二', '吉', '艮其腓，不拯其随，其心不快。', '止住腿肚子，不拯救跟随的人，心里不愉快。', '不拯其随，未退听也。', '不拯救跟随的人，说明没有退听。', '', '得此爻者，会不愉快，须防不拯救跟随的人。做官的须防不愉快。');
addYao(52, 3, '九三', '平', '艮其限，列其夤，厉熏心。', '止住腰部，裂开脊背，危险像火熏心。', '艮其限，危熏心也。', '止住腰部，说明危险像火熏心。', '', '得此爻者，会有危险，须防火熏心。做官的须防危险。');
addYao(52, 4, '六四', '平', '艮其身，无咎。', '止住身体，没有灾祸。', '艮其身，止诸躬也。', '止住身体，说明止住自身。', '', '得此爻者，宜止住身体，没有灾祸。做官的须防身体。');
addYao(52, 5, '六五', '吉', '艮其辅，言有序，悔亡。', '止住面颊，言语有秩序，悔恨消失。', '艮其辅，以中正也。', '止住面颊，因为居位中正。', '', '得此爻者，言语有秩序，悔恨消失。做官的须防言语。');
addYao(52, 6, '上九', '平', '敦艮，吉。', '敦厚地止住，吉利。', '敦艮之吉，以厚终也。', '敦厚地止住吉利，说明以厚道终结。', '', '得此爻者，敦厚地止住，吉利。做官的须防不敦厚。');

// 53. 渐卦 (110100)
addYao(53, 1, '初六', '平', '鸿渐于干，小子厉，有言，无咎。', '大雁渐渐飞到水边，小子有危险，有言语之争，但没有灾祸。', '小子之厉，义无咎也。', '小子的危险，从道义上说没有灾祸。', '', '得此爻者，会有危险，但没有灾祸。做官的须防危险。');
addYao(53, 2, '六二', '吉', '鸿渐于磐，饮食衎衎，吉。', '大雁渐渐飞到磐石上，饮食快乐，吉利。', '饮食衎衎，不素饱也。', '饮食快乐，说明不是白白吃饱。', '', '得此爻者，会有饮食快乐，吉利。做官的会得到快乐。');
addYao(53, 3, '九三', '平', '鸿渐于陆，夫征不复，妇孕不育，凶。利御寇。', '大雁渐渐飞到陆地上，丈夫出征不回来，妻子怀孕不生育，凶险。利于防御寇盗。', '夫征不复，离群丑也。妇孕不育，失其道也。利御寇，顺相保也。', '丈夫出征不回来，说明离开群体。妻子怀孕不生育，说明失去了道义。利于防御寇盗，说明互相保护。', '', '得此爻者，会有凶险，但利于防御寇盗。做官的须防凶险。');
addYao(53, 4, '六四', '平', '鸿渐于木，或得其桷，无咎。', '大雁渐渐飞到树上，有的得到了方形的椽子，没有灾祸。', '或得其桷，顺以巽也。', '有的得到了方形的椽子，说明顺从谦逊。', '', '得此爻者，会得到方形的椽子，没有灾祸。做官的会得到帮助。');
addYao(53, 5, '九五', '吉', '鸿渐于陵，妇三岁不孕，终莫之胜，吉。', '大雁渐渐飞到丘陵上，妻子三年不怀孕，最终没有人能胜过她，吉利。', '终莫之胜吉，得所愿也。', '最终没有人能胜过她吉利，说明得到了愿望。', '', '得此爻者，会有三年不怀孕，但最终吉利。做官的会得到愿望。');
addYao(53, 6, '上九', '平', '鸿渐于逵，其羽可用为仪，吉。', '大雁渐渐飞到四通八达的大道上，它的羽毛可以用来做仪式，吉利。', '其羽可用为仪，吉，不可乱也。', '它的羽毛可以用来做仪式吉利，说明不可混乱。', '', '得此爻者，会有羽毛可以做仪式，吉利。做官的会得到仪式。');

// 54. 归妹卦 (001101)
addYao(54, 1, '初九', '平', '归妹以娣，跛能履，征吉。', '嫁妹妹做妾，脚跛能走路，出征吉利。', '归妹以娣，以恒也。跛能履，吉相承也。', '嫁妹妹做妾，说明有恒心。脚跛能走路，说明吉利相承。', '', '得此爻者，会嫁妹妹做妾，出征吉利。做官的会得到吉利。');
addYao(54, 2, '九二', '吉', '眇能视，利幽人之贞。', '眼睛瞎了一只还能看，利于幽人的贞卜。', '利幽人之贞，未变常也。', '利于幽人的贞卜，说明没有改变常态。', '', '得此爻者，眼睛瞎了一只还能看，利于幽人的贞卜。做官的会得到好处。');
addYao(54, 3, '六三', '凶', '归妹以须，反归以娣。', '嫁妹妹等待，反而回来做妾。', '归妹以须，未当也。', '嫁妹妹等待，说明位置不当。', '', '得此爻者，会有等待，但位置不当。做官的须防位置不当。');
addYao(54, 4, '九四', '平', '归妹愆期，迟归有时。', '嫁妹妹延期，推迟出嫁有时间。', '愆期之志，有待而行也。', '延期的志向，说明有待而行。', '', '得此爻者，会延期，但有待而行。做官的须防延期。');
addYao(54, 5, '六五', '吉', '帝乙归妹，其君之袂不如其娣之袂良，月几望，吉。', '殷帝乙嫁女，她的衣袖不如她的陪嫁妹妹的衣袖好，月亮接近满月，吉利。', '帝乙归妹，不如其娣之袂良也。其位在中，以贵行也。', '殷帝乙嫁女不如她的陪嫁妹妹的衣袖好。她的位置在中间，说明以尊贵行事。', '', '得此爻者，会有嫁女之事，吉利。做官的会得到吉利。');
addYao(54, 6, '上六', '平', '女承筐无实，士刲羊无血，无攸利。', '女子捧着筐没有果实，男子杀羊没有血，没有好处。', '上六无实，承虚筐也。', '上六没有果实，说明捧着空筐。', '', '得此爻者，会没有果实，没有好处。做官的须防没有好处。');

// 55. 丰卦 (101100)
addYao(55, 1, '初九', '平', '遇其配主，虽旬无咎，往有尚。', '遇到他的配偶主人，虽然十天没有灾祸，前往有嘉奖。', '虽旬无咎，过旬灾也。', '虽然十天没有灾祸，超过十天会有灾难。', '', '得此爻者，会遇到配偶主人，前往有嘉奖。做官的会得到嘉奖。');
addYao(55, 2, '六二', '吉', '丰其蔀，日中见斗，往得疑疾，有孚发若，吉。', '扩大他的蔽障，中午看见北斗星，前往会得到疑虑疾病，有诚信发作，吉利。', '有孚发若，信以发志也。', '有诚信发作，说明以诚信发志。', '', '得此爻者，会有疑虑疾病，但有诚信发作，吉利。做官的会得到吉利。');
addYao(55, 3, '九三', '平', '丰其沛，日中见沬，折其右肱，无咎。', '扩大他的幡幔，中午看见小星星，折断了他的右臂，没有灾祸。', '丰其沛，不可大事也。折其右肱，终不可用也。', '扩大他的幡幔，说明不可以做大事。折断了他的右臂，说明最终不可用。', '', '得此爻者，会折断右臂，但没有灾祸。做官的须防折断右臂。');
addYao(55, 4, '九四', '平', '丰其蔀，日中见斗，遇其夷主，吉。', '扩大他的蔽障，中午看见北斗星，遇到他的夷族主人，吉利。', '丰其蔀，位不当也。日中见斗，幽不明也。遇其夷主，吉行也。', '扩大他的蔽障，说明位置不当。中午看见北斗星，说明幽暗不明。遇到他的夷族主人，说明吉利的行动。', '', '得此爻者，会遇到夷族主人，吉利。做官的会得到吉利。');
addYao(55, 5, '六五', '吉', '来章，有庆誉，吉。', '送来文采，有喜庆荣誉，吉利。', '六五之吉，有庆也。', '六五爻辞讲吉利，说明有喜庆。', '', '得此爻者，会有文采，有喜庆荣誉，吉利。做官的会得到荣誉。');
addYao(55, 6, '上六', '平', '丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶。', '扩大他的房屋，遮蔽他的家，窥视他的门户，寂静没有人，三年不见人，凶险。', '丰其屋，天际翔也。窥其户阒其无人，自藏也。', '扩大他的房屋，说明在天际飞翔。窥视他的门户寂静没有人，说明自我隐藏。', '', '得此爻者，会有凶险，须防自我隐藏。做官的须防凶险。');

// 56. 旅卦 (001011)
addYao(56, 1, '初六', '平', '旅琐琐，斯其所取灾。', '旅行琐碎，这是他所取的灾难。', '旅琐琐，志穷灾也。', '旅行琐碎，说明志向穷困带来灾难。', '', '得此爻者，会有琐碎，须防灾难。做官的须防琐碎。');
addYao(56, 2, '六二', '吉', '旅即次，怀其资，得童仆贞。', '旅行到达住所，怀着他的资财，得到童仆贞卜。', '得童仆贞，终无尤也。', '得到童仆贞卜，说明最终没有灾祸。', '', '得此爻者，会到达住所，得到童仆，吉利。做官的会得到好处。');
addYao(56, 3, '九三', '平', '旅焚其次，丧其童仆，贞厉。', '旅行烧毁了他的住所，丧失了他的童仆，贞卜危险。', '旅焚其次，亦以伤矣。以旅与下，其义丧也。', '旅行烧毁了他的住所，说明也受伤了。以旅行的身份对待下面的人，从道义上说会丧失。', '', '得此爻者，会烧毁住所，丧失童仆，危险。做官的须防危险。');
addYao(56, 4, '九四', '平', '旅于处，得其资斧，我心不快。', '旅行在住处，得到他的资财斧头，我心里不愉快。', '旅于处，未得位也。得其资斧，心未快也。', '旅行在住处，说明没有得到位置。得到他的资财斧头，说明心里不愉快。', '', '得此爻者，会得到资财斧头，但心里不愉快。做官的须防不愉快。');
addYao(56, 5, '六五', '吉', '射雉一矢亡，终以誉命。', '射野鸡一箭丢失，最终以荣誉命令。', '终以誉命，上逮也。', '最终以荣誉命令，说明上达。', '', '得此爻者，会有一箭丢失，但最终以荣誉命令。做官的会得到荣誉。');
addYao(56, 6, '上九', '平', '鸟焚其巢，旅人先笑后号啕。丧牛于易，凶。', '鸟烧毁了它的巢，旅人先笑后哭号。丧失牛在狄人那里，凶险。', '以旅在上，其义焚也。丧牛于易，终莫之闻也。', '以旅行的身份在上位，从道义上说会被烧毁。丧失牛在狄人那里，说明最终没有人听说。', '', '得此爻者，会有凶险，须防先笑后哭号。做官的须防凶险。');

// 57. 巽卦 (110110)
addYao(57, 1, '初六', '平', '进退，利武人之贞。', '进退，利于武人的贞卜。', '进退，志疑也。利武人之贞，志治也。', '进退，说明志向疑惑。利于武人的贞卜，说明志向得到治理。', '', '得此爻者，会有进退，利于武人的贞卜。做官的会得到治理。');
addYao(57, 2, '九二', '吉', '巽在床下，用史巫纷若，吉，无咎。', '谦逊在床下，用史官巫祝纷纷，吉利，没有灾祸。', '纷若之吉，得中也。', '纷纷的吉利，说明得到中道。', '', '得此爻者，会有谦逊，用史官巫祝纷纷，吉利。做官的会得到中道。');
addYao(57, 3, '九三', '平', '频巽，吝。', '频繁谦逊，有困难。', '频巽之吝，志穷也。', '频繁谦逊的困难，说明志向穷困。', '', '得此爻者，会有频繁谦逊，有困难。做官的须防频繁谦逊。');
addYao(57, 4, '六四', '平', '悔亡，田获三品。', '悔恨消失，打猎获得三种猎物。', '田获三品，有功也。', '打猎获得三种猎物，说明有功劳。', '', '得此爻者，会有悔恨消失，打猎获得三种猎物。做官的会得到功劳。');
addYao(57, 5, '九五', '吉', '贞吉，悔亡，无不利。无初有终。先庚三日，后庚三日，吉。', '贞卜吉利，悔恨消失，无所不利。没有开始有终结。庚日前三天，庚日后三天，吉利。', '九五之吉，位正中也。', '九五爻辞讲吉利，因为居位正中。', '', '得此爻者，会有吉利，无所不利。做官的会得到正中。');
addYao(57, 6, '上九', '平', '巽在床下，丧其资斧，贞凶。', '谦逊在床下，丧失了他的资财斧头，贞卜凶险。', '巽在床下，上穷也。丧其资斧，正乎凶也。', '谦逊在床下，说明在上位穷困。丧失了他的资财斧头，说明正逢凶险。', '', '得此爻者，会有凶险，须防丧失资财斧头。做官的须防凶险。');

// 58. 兑卦 (011011)
addYao(58, 1, '初九', '平', '和兑，吉。', '和谐喜悦，吉利。', '和兑之吉，行未疑也。', '和谐喜悦的吉利，说明行动没有疑虑。', '', '得此爻者，会有和谐喜悦，吉利。做官的会得到和谐。');
addYao(58, 2, '九二', '吉', '孚兑，吉，悔亡。', '诚信喜悦，吉利，悔恨消失。', '孚兑之吉，信志也。', '诚信喜悦的吉利，说明诚信志向。', '', '得此爻者，会有诚信喜悦，吉利。做官的会得到诚信。');
addYao(58, 3, '六三', '凶', '来兑，凶。', '前来喜悦，凶险。', '来兑之凶，位不当也。', '前来喜悦的凶险，说明位置不当。', '', '得此爻者，会有前来喜悦，凶险。做官的须防位置不当。');
addYao(58, 4, '九四', '平', '商兑未宁，介疾有喜。', '商量喜悦没有安宁，小疾病有喜庆。', '九四之喜，有庆也。', '九四爻辞讲的喜庆，说明有庆贺。', '', '得此爻者，会有商量喜悦，小疾病有喜庆。做官的会得到庆贺。');
addYao(58, 5, '九五', '吉', '孚于剥，有厉。', '诚信被剥落，有危险。', '孚于剥，位正当也。', '诚信被剥落，说明位置正当。', '', '得此爻者，会有诚信被剥落，有危险。做官的须防危险。');
addYao(58, 6, '上六', '平', '引兑。', '引导喜悦。', '上六引兑，未光也。', '上六引导喜悦，说明尚未发扬光大。', '', '得此爻者，会有引导喜悦。做官的须防未光大。');

// 59. 涣卦 (110010)
addYao(59, 1, '初六', '平', '用拯马壮，吉。', '用强壮的马拯救，吉利。', '初六之吉，顺也。', '初六爻辞讲的吉利，说明顺从。', '', '得此爻者，会有强壮的马拯救，吉利。做官的会得到拯救。');
addYao(59, 2, '九二', '吉', '涣奔其机，悔亡。', '涣散奔向他的机座，悔恨消失。', '涣奔其机，得愿也。', '涣散奔向他的机座，说明得到愿望。', '', '得此爻者，会有涣散，但奔向机座，悔恨消失。做官的会得到愿望。');
addYao(59, 3, '六三', '平', '涣其躬，无悔。', '涣散他的身体，没有悔恨。', '涣其躬，志在外也。', '涣散他的身体，说明志向在外面。', '', '得此爻者，会有涣散身体，没有悔恨。做官的须防志向在外。');
addYao(59, 4, '六四', '平', '涣其群，元吉。涣有丘，匪夷所思。', '涣散他的群体，大吉大利。涣散有山丘，不是平常人所能想到的。', '涣其群元吉，光大也。', '涣散他的群体大吉大利，说明发扬光大。', '', '得此爻者，会有涣散群体，大吉大利。做官的会得到光大。');
addYao(59, 5, '九五', '吉', '涣汗其大号，涣王居，无咎。', '涣散像大汗淋漓一样大声号叫，涣散君王的居处，没有灾祸。', '王居无咎，正位也。', '君王的居处没有灾祸，说明位置正当。', '', '得此爻者，会有涣散，没有灾祸。做官的会得到正位。');
addYao(59, 6, '上九', '平', '涣其血去逖出，无咎。', '涣散他的血离开远出，没有灾祸。', '涣其血，远害也。', '涣散他的血，说明远离祸害。', '', '得此爻者，会有涣散血，远离祸害，没有灾祸。做官的会远离祸害。');

// 60. 节卦 (010011)
addYao(60, 1, '初九', '平', '不出户庭，无咎。', '不出门户庭院，没有灾祸。', '不出户庭，知通塞也。', '不出门户庭院，说明知道通畅和阻塞。', '', '得此爻者，宜不出门户庭院，没有灾祸。做官的须防出门。');
addYao(60, 2, '九二', '吉', '不出门庭，凶。', '不出门庭，凶险。', '不出门庭凶，失时极也。', '不出门庭凶险，说明失去了时机的极致。', '', '得此爻者，会有凶险，须防不出门庭。做官的须防不出门庭。');
addYao(60, 3, '六三', '平', '不节若，则嗟若，无咎。', '不节制，就叹息，没有灾祸。', '不节之嗟，又谁咎也。', '不节制的叹息，又能责怪谁呢。', '', '得此爻者，会有不节制，但叹息，没有灾祸。做官的须防不节制。');
addYao(60, 4, '六四', '平', '安节，亨。', '安于节制，亨通。', '安节之亨，承上道也。', '安于节制的亨通，说明承继上面的道义。', '', '得此爻者，会有安于节制，亨通。做官的会承继道义。');
addYao(60, 5, '九五', '吉', '甘节，吉，往有尚。', '甘甜的节制，吉利，前往有嘉奖。', '甘节之吉，居位中也。', '甘甜的节制吉利，因为居位正中。', '', '得此爻者，会有甘甜的节制，吉利。做官的会得到嘉奖。');
