// 61. 中孚卦 (110011)
addYao(61, 1, '初九', '平', '虞吉，有它不燕。', '预料吉利，有其他事情不安宁。', '初九虞吉，志未变也。', '初九预料吉利，说明志向没有改变。', '', '得此爻者，会有预料吉利，有其他事情不安宁。做官的须防其他事情。');
addYao(61, 2, '九二', '吉', '鸣鹤在阴，其子和之。我有好爵，吾与尔靡之。', '鹤在阴暗处鸣叫，它的孩子应和它。我有好的爵位，我和你分享它。', '其子和之，中心愿也。', '它的孩子应和它，说明内心愿意。', '', '得此爻者，会有鹤鸣叫，孩子应和，分享爵位。做官的会得到分享。');
addYao(61, 3, '六三', '平', '得敌，或鼓或罢，或泣或歌。', '得到敌人，有的击鼓有的罢手，有的哭泣有的唱歌。', '或鼓或罢，位不当也。', '有的击鼓有的罢手，说明位置不当。', '', '得此爻者，会有敌人，须防位置不当。做官的须防敌人。');
addYao(61, 4, '六四', '平', '月几望，马匹亡，无咎。', '月亮接近满月，马匹丢失，没有灾祸。', '马匹亡，绝类上也。', '马匹丢失，说明断绝了同类而向上。', '', '得此爻者，会有马匹丢失，但没有灾祸。做官的会断绝同类而向上。');
addYao(61, 5, '九五', '吉', '有孚挛如，无咎。', '有诚信紧紧相连，没有灾祸。', '有孚挛如，位正当也。', '有诚信紧紧相连，说明位置正当。', '', '得此爻者，会有诚信紧紧相连，没有灾祸。做官的会得到正当位置。');
addYao(61, 6, '上九', '平', '翰音登于天，贞凶。', '鸡的声音登上天空，贞卜凶险。', '翰音登于天，何可长也。', '鸡的声音登上天空，怎么可能长久呢。', '', '得此爻者，会有凶险，须防鸡的声音登于天。做官的须防凶险。');

// 62. 小过卦 (001100)
addYao(62, 1, '初六', '平', '飞鸟以凶。', '飞鸟带来凶险。', '飞鸟以凶，不可如何也。', '飞鸟带来凶险，说明不可如何。', '', '得此爻者，会有凶险，须防飞鸟。做官的须防凶险。');
addYao(62, 2, '六二', '吉', '过其祖，遇其妣，不及其君，遇其臣，无咎。', '超过他的祖父，遇到他的祖母，不超过他的君王，遇到他的臣子，没有灾祸。', '不及其君，臣不可过也。', '不超过他的君王，说明臣子不可以超过。', '', '得此爻者，会有超过祖父，遇到祖母，没有灾祸。做官的会得到臣子。');
addYao(62, 3, '九三', '平', '弗过防之，从或戕之，凶。', '不超过就防范他，跟从或者伤害他，凶险。', '从或戕之，凶如何也。', '跟从或者伤害他，凶险如何呢。', '', '得此爻者，会有凶险，须防伤害。做官的须防凶险。');
addYao(62, 4, '九四', '平', '无咎，弗过遇之。往厉必戒，勿用永贞。', '没有灾祸，不超过就遇到他。前往危险必须警戒，不可使用永久贞卜。', '弗过遇之，位不当也。往厉必戒，终不可长也。', '不超过就遇到他，说明位置不当。前往危险必须警戒，说明最终不可长久。', '', '得此爻者，会有遇到，但须防危险。做官的须防位置不当。');
addYao(62, 5, '六五', '吉', '密云不雨，自我西郊。公弋取彼在穴。', '浓云密布不下雨，从我西郊来。王公射取在洞穴里的东西。', '密云不雨，已上也。', '浓云密布不下雨，说明已经在上位。', '', '得此爻者，会有浓云不雨，王公射取，吉利。做官的会得到射取。');
addYao(62, 6, '上六', '平', '弗遇过之，飞鸟离之，凶，是谓灾眚。', '不遇到就超过他，飞鸟离开他，凶险，这叫做灾难。', '弗遇过之，已亢也。', '不遇到就超过他，说明已经高亢。', '', '得此爻者，会有凶险，须防飞鸟离开。做官的须防高亢。');

// 63. 既济卦 (101010)
addYao(63, 1, '初九', '平', '曳其轮，濡其尾，无咎。', '拖着车轮，打湿尾巴，没有灾祸。', '曳其轮，义无咎也。', '拖着车轮，从道义上说没有灾祸。', '', '得此爻者，会有拖着车轮，打湿尾巴，没有灾祸。做官的会得到道义。');
addYao(63, 2, '六二', '吉', '妇丧其茀，勿逐，七日得。', '妇人丢失了她的头饰，不要追逐，七天会得到。', '七日得，以中道也。', '七天会得到，说明因为中道。', '', '得此爻者，会有丢失头饰，但七天会得到。做官的会得到中道。');
addYao(63, 3, '九三', '平', '高宗伐鬼方，三年克之，小人勿用。', '高宗讨伐鬼方，三年攻克它，小人不要任用。', '三年克之，惫也。', '三年攻克它，说明疲惫。', '', '得此爻者，会有讨伐，但三年攻克，小人勿用。做官的须防疲惫。');
addYao(63, 4, '六四', '平', '繻有衣袽，终日戒。', '有破旧的衣服，整天警戒。', '终日戒，有所疑也。', '整天警戒，说明有所疑虑。', '', '得此爻者，会有破旧的衣服，整天警戒。做官的须防疑虑。');
addYao(63, 5, '九五', '吉', '东邻杀牛，不如西邻之禴祭，实受其福。', '东边邻居杀牛祭祀，不如西边邻居的薄祭，实际受到福气。', '东邻杀牛，不如西邻之时也。实受其福，吉大来也。', '东边邻居杀牛不如西边邻居的时机。实际受到福气，说明吉利大来。', '', '得此爻者，会有薄祭，实际受到福气。做官的会得到时机。');
addYao(63, 6, '上六', '平', '濡其首，厉。', '打湿头部，危险。', '濡其首厉，何可久也。', '打湿头部危险，怎么可能长久呢。', '', '得此爻者，会有危险，须防打湿头部。做官的须防危险。');

// 64. 未济卦 (010101)
addYao(64, 1, '初六', '平', '濡其尾，吝。', '打湿尾巴，有困难。', '濡其尾，亦不知极也。', '打湿尾巴，说明也不知道极限。', '', '得此爻者，会有困难，须防打湿尾巴。做官的须防困难。');
addYao(64, 2, '九二', '吉', '曳其轮，贞吉。', '拖着车轮，贞卜吉利。', '九二贞吉，中以行正也。', '九二爻辞讲贞卜吉利，说明居中行事正当。', '', '得此爻者，会有拖着车轮，贞卜吉利。做官的会得到正当。');
addYao(64, 3, '六三', '平', '未济，征凶，利涉大川。', '没有渡过，出征凶险，利于涉水渡河。', '未济征凶，位不当也。', '没有渡过出征凶险，说明位置不当。', '', '得此爻者，会有出征凶险，但利于涉水渡河。做官的须防位置不当。');
addYao(64, 4, '九四', '平', '贞吉，悔亡。震用伐鬼方，三年有赏于大国。', '贞卜吉利，悔恨消失。用震动讨伐鬼方，三年在大国受赏。', '贞吉悔亡，志行也。', '贞卜吉利悔恨消失，说明志向得以实行。', '', '得此爻者，会有讨伐，三年受赏。做官的会得到志向实行。');
addYao(64, 5, '六五', '吉', '贞吉，无悔。君子之光，有孚吉。', '贞卜吉利，没有悔恨。君子的光辉，有诚信吉利。', '君子之光，其晖吉也。', '君子的光辉，说明他的光辉吉利。', '', '得此爻者，会有君子的光辉，有诚信吉利。做官的会得到光辉。');
addYao(64, 6, '上九', '平', '有孚于饮酒，无咎。濡其首，有孚失是。', '有诚信饮酒，没有灾祸。打湿头部，有诚信但失去了正道。', '饮酒濡首，亦不知节也。', '饮酒打湿头部，说明也不知道节制。', '', '得此爻者，会有饮酒，但须防打湿头部。做官的须防不知节制。');

const files = [
  { name: 'yao-data-1.json', range: [1, 10] },
  { name: 'yao-data-2.json', range: [11, 20] },
  { name: 'yao-data-3.json', range: [21, 30] },
  { name: 'yao-data-4.json', range: [31, 40] },
  { name: 'yao-data-5.json', range: [41, 50] },
  { name: 'yao-data-6.json', range: [51, 64] }
];

files.forEach(file => {
  let data = [];
  for (let id = file.range[0]; id <= file.range[1]; id++) {
    const hex = hexagrams.find(h => h.id === id);
    if (!hex) continue;
    
    for (let pos = 1; pos <= 6; pos++) {
      const existing = yaoData[id] ? yaoData[id].find(y => y.position === pos) : null;
      if (existing) {
        data.push(existing);
      } else {
        const yaoTypes = ['初九', '九二', '九三', '九四', '九五', '上九'];
        const yinYaoTypes = ['初六', '六二', '六三', '六四', '六五', '上六'];
        const symbol = hex.symbol;
        const isYin = symbol.charAt(6 - pos) === '0';
        data.push({
          hexagramId: id,
          position: pos,
          yaoType: isYin ? yinYaoTypes[pos - 1] : yaoTypes[pos - 1],
          fortune: '',
          yaoText: '',
          yaoTextTranslation: '',
          xiangText: '',
          xiangTextTranslation: '',
          heloNumber: '',
          heloDescription: ''
        });
      }
    }
  }
  fs.writeFileSync(`src/data/${file.name}`, JSON.stringify(data, null, 2));
  const filled = data.filter(d => d.yaoText).length;
  console.log(`${file.name}: ${filled}/${data.length} filled`);
});

console.log('Total entries written:', files.reduce((sum, f) => {
  const d = JSON.parse(fs.readFileSync(`src/data/${f.name}`));
  return sum + d.length;
}, 0));